(window.TRENER_PACKS=window.TRENER_PACKS||{})["osnovy-genetiki-izmenchivost"]={"id": "osnovy-genetiki-izmenchivost", "subject": "Биология", "title": "Основы и методы генетики, изменчивость и наследственные заболевания человека", "version": "22.11.2026", "konspekt": "osnovy-genetiki-izmenchivost", "codes": ["3.2", "3.4", "3.5"], "kod": {"p": [{"id": "p1", "t": "Масштабы генетики: от гена к популяции", "x": "Генотип — все гены одной особи; фенотип — все её признаки; геном — все гены гаплоидного набора вида (n); кариотип — число, форма и размеры хромосом соматической клетки вида (2n); генофонд — все гены всех особей популяции.", "ref": "01.15"}, {"id": "p2", "t": "Выбор метода генетики по объекту", "x": "Скрещивание — гибридологический; родословная — генеалогический; роль среды и генотипа — близнецовый; хромосомы под микроскопом — цитогенетический; ферменты и метаболиты в крови/моче — биохимический; последовательность нуклеотидов ДНК — молекулярно-генетический (секвенирование); частоты аллелей в группах — популяционно-статистический.", "ref": "02.7"}, {"id": "p3", "t": "Эвристика КИМ: быстрое распознавание вида изменчивости", "x": "Прямая зависимость от условий среды → модификационная. Упоминание наследственного заболевания или внезапного появления нового признака у одной особи в группе → мутационная. Отсылка к признакам родителей (при этом не болезнь, а новое сочетание) → комбинативная.", "ref": "03.4"}, {"id": "p4", "t": "Модификации и норма реакции", "x": "Модификационная изменчивость меняет только фенотип в пределах нормы реакции, не затрагивая ДНК и не передаваясь по наследству. Наследуется сама норма реакции — диапазон возможного варьирования признака. На вариационной кривой по оси X откладывают значения признака (варианты v), по оси Y — частоту встречаемости (p).", "ref": "03.6"}, {"id": "p5", "t": "Три источника комбинативной изменчивости", "x": "Новые сочетания уже существующих аллелей без мутаций возникают благодаря: 1) кроссинговеру в профазе I мейоза; 2) независимому расхождению негомологичных хромосом в анафазе I мейоза; 3) случайному слиянию гамет при оплодотворении.", "ref": "04.6"}, {"id": "p6", "t": "Закон гомологических рядов Н. И. Вавилова", "x": "Генетически близкие виды и роды имеют сходные ряды наследственной изменчивости, потому что произошли от общего предка и унаследовали набор гомологичных генов. Закон позволяет прогнозировать нужные формы в селекции и подбирать животных-моделей для изучения болезней человека.", "ref": "04.12"}, {"id": "p7", "t": "Три уровня мутаций: буква → участок → число хромосом", "x": "Генные мутации меняют нуклеотиды внутри одного гена (вставка/выпадение некратного 3 числа нуклеотидов даёт сдвиг рамки считывания). Хромосомные меняют структуру хромосом (делеция, дупликация, инверсия, транслокация). Геномные меняют число хромосом (полиплоидия — кратно n; анеуплоидия — некратно n).", "ref": "05.8"}, {"id": "p8", "t": "Механизм полиплоидии (колхицин) и анеуплоидии (мейоз)", "x": "Колхицин разрушает микротрубочки веретена деления → хромосомы не расходятся в анафазе → кратное увеличение набора (полиплоидия). Нерасхождение одной пары гомологичных хромосом в анафазе I или хроматид в анафазе II мейоза даёт аномальные гаметы (n+1 и n−1), а после оплодотворения — трисомию (47) или моносомию (45).", "ref": "06.20"}, {"id": "p9", "t": "Три рубежа медицинской генетики и стволовые клетки", "x": "Медицинская генетика снижает риск болезней через профилактику (консультирование, отказ от близкородственных браков), раннюю диагностику (амниоцентез, биопсия хориона, неонатальный скрининг) и коррекцию фенотипа (диета при ФКУ и галактоземии). Стволовые клетки недифференцированы, способны к самообновлению и дифференцировке (тоти- → плюри- → мульти- → унипотентные).", "ref": "07.4"}, {"id": "p10", "t": "Алгоритм экспериментальных заданий № 22–23", "x": "Всегда разделяй независимую (задаваемую) и зависимую (измеряемую) переменные. Нулевая гипотеза утверждает отсутствие зависимости между ними. Большая выборка снижает влияние индивидуальной изменчивости и повышает достоверность, а нарушение равенства прочих условий (возраста, генотипа, полива) не позволяет установить зависимость в явном виде.", "ref": "07.15"}], "z": [{"id": "z1", "x": "Ген кодирует первичную структуру одного полипептида (белка) ИЛИ молекулу функциональной РНК (тРНК, рРНК) — писать «только один белок» неточно.", "sk": "terms", "ref": "01.7"}, {"id": "z2", "x": "Доминантный признак подавляет рецессивный у Aa только при полном доминировании; при неполном доминировании у гетерозиготы проявляется промежуточный признак.", "sk": "terms", "ref": "01.19"}, {"id": "z3", "x": "Цитогенетический метод (микроскопия кариотипа) НЕ видит генные (точковые) мутации — только геномные и крупные хромосомные.", "sk": "methods", "ref": "02.8"}, {"id": "z4", "x": "Удойность коров (количество молока) имеет широкую норму реакции, а жирность молока — узкую.", "sk": "modif", "ref": "03.9"}, {"id": "z5", "x": "Не все модификации обратимы: искривление костей при рахите сохраняется на всю жизнь, но это всё равно модификация, так как ДНК не изменена.", "sk": "modif", "ref": "03.11"}, {"id": "z6", "x": "При модификациях в новых условиях меняется только фенотип в пределах нормы реакции — сама норма реакции (заданная генотипом) НЕ меняется.", "sk": "modif", "ref": "03.20"}, {"id": "z7", "x": "Сама по себе конъюгация — лишь сближение гомологичных хромосом; новые комбинации аллелей создаёт обмен участками — кроссинговер в профазе I.", "sk": "comb", "ref": "04.7"}, {"id": "z8", "x": "Анеуплоидия (гетероплоидия) — это не только увеличение (2n+1), но и уменьшение числа хромосом (2n−1, например 45, X0).", "sk": "mut", "ref": "05.19"}, {"id": "z9", "x": "Соматические мутации не передаются при половом размножении, но передаются при вегетативном (бесполом) размножении (черенкованием, прививкой).", "sk": "mut", "ref": "05.22"}, {"id": "z10", "x": "Синдром Клайнфельтера — это 47, XXY (лишняя X-хромосома у мужчин). Кариотип 47, XYY — отдельный синдром Якобса!", "sk": "diseases", "ref": "06.17"}, {"id": "z11", "x": "Синдром Дауна (47, +21) в классификации мутаций ЕГЭ — геномная мутация, а синдром «кошачьего крика» (46, 5p−) — хромосомная (делеция).", "sk": "diseases", "ref": "06.16"}, {"id": "z12", "x": "Галактоземия — нарушение обмена моносахарида галактозы (а не лактозы). Врождённый порок может быть ненаследственным (от тератогенов).", "sk": "diseases", "ref": "06.11"}]}, "skills": [{"id": "terms", "name": "Язык генетики и символика", "ref": "01", "idea": "Разводить 5 созвучных терминов по уровню организации (особь / гаплоидный вид / диплоидный вид / популяция) и точно читать записи P, G, F_{1}, гомо- и гетерозигот.", "pre": {"type": "one", "q": "Чем на ЕГЭ отличается понятие «геном» от понятия «кариотип»?", "o": ["Геном — все гены гаплоидного набора вида (n), а кариотип — признаки хромосом соматической клетки вида (2n)", "Геном — это хромосомы одной особи, а кариотип — все гены популяции", "Геном и кариотип — полные синонимы для диплоидного набора", "Геном описывает только половые хромосомы, а кариотип — только аутосомы"], "a": 0, "ex": "Геном характеризует именно совокупность генов гаплоидного набора вида (n = 23 у человека), а кариотип — число, форму и размеры хромосом диплоидной соматической клетки вида (2n = 46).", "d": {"1": "Все гены популяции — это генофонд, а не кариотип.", "2": "На ЕГЭ их строго различают по гаплоидности/диплоидности и по объекту (гены vs морфология хромосом).", "3": "Оба термина охватывают и аутосомы, и половые хромосомы."}}, "pair": {"type": "one", "cases": [["Случай А", "В соматической клетке организма 46 хромосом определённой формы и размеров (22 пары аутосом и пара XY)."], ["Случай Б", "В 23 хромосомах яйцеклетки человека содержится полный набор всех генов данного биологического вида."]], "q": "Какие два термина точно соответствуют случаям А и Б?", "o": ["А — кариотип, Б — геном", "А — геном, Б — кариотип", "А — генотип, Б — генофонд", "А — фенотип, Б — генотип"], "a": 0, "ex": "Случай А описывает морфологические признаки и число хромосом диплоидной соматической клетки (кариотип). Случай Б — совокупность всех генов гаплоидного набора вида (геном).", "d": {"1": "Термины перепутаны местами: 46 хромосом соматической клетки — кариотип, а гены 23 хромосом — геном.", "2": "Генофонд относится к целой популяции, а не к гаплоидному набору вида.", "3": "Фенотип — это признаки организма (цвет глаз, рост), а не набор хромосом."}}, "fade": {"q": "Определи термины по описаниям из заданий № 6 КИМ:", "steps": ["1. Все гены, расположенные в 23 хромосомах гаметы человека — это {геном|кариотип|генофонд}.", "2. Число, форма и размеры 46 хромосом соматической клетки человека — это {кариотип|геном|генотип}.", "3. Совокупность всех аллелей генов всех особей в изолированной популяции — это {генофонд|генотип|геном}.", "4. Два разных варианта одного гена (A и a), лежащие в одинаковых {локусах|центромерах|теломерах} гомологичных хромосом, называют {аллельными|сцепленными|неаллельными} генами."], "why": "Проверяй два маркера: объект (гены vs хромосомы) и масштаб (особь → гаплоидный вид → диплоидный вид → популяция)."}, "bug": {"q": "Ученик написал краткую шпаргалку по терминам генетики. Найди шаг с биологической ошибкой:", "steps": ["Ген — участок молекулы ДНК, кодирующий первичную структуру полипептида или молекулу функциональной РНК.", "Гомологичные хромосомы имеют одинаковую форму, размер и набор локусов генов.", "Доминантный признак всегда проявляется в фенотипе у всех особей, имеющих хотя бы один доминантный аллель.", "Чистая линия — группа гомозиготных особей, не дающая расщепления при самоопылении."], "bad": 2, "fix": "Доминантный признак полностью подавляет рецессивный у гетерозиготы Aa только при полном доминировании; при неполном доминировании у Aa развивается промежуточный признак.", "why": "Слово «всегда» — ловушка ФИПИ. Например, у ночной красавицы гетерозигота Aa имеет розовые, а не красные цветки."}, "recall": {"q": "Назови по памяти различия между пятью терминами: генотип, фенотип, геном, кариотип, генофонд.", "points": ["Генотип — совокупность всех генов одной особи.", "Фенотип — совокупность всех внешних и внутренних признаков особи.", "Геном — совокупность всех генов гаплоидного набора хромосом вида (n).", "Кариотип — совокупность признаков хромосом (число, форма, размеры) соматической клетки вида (2n).", "Генофонд — совокупность всех генов (аллелей) всех особей популяции."]}}, {"id": "methods", "name": "Методы генетики и кариотипирование", "ref": "02", "idea": "Подбирать точный метод по объекту исследования, знать этапы кариотипирования и не путать цитогенетический анализ с биохимическим и секвенированием.", "pre": {"type": "one", "q": "Какой метод генетики человека НЕ позволит выявить фенилкетонурию (точковую генную мутацию)?", "o": ["Цитогенетический", "Биохимический", "Молекулярно-генетический (секвенирование)", "Генеалогический (для оценки риска в семье)"], "a": 0, "ex": "Цитогенетический метод изучает хромосомы под световым микроскопом и выявляет только геномные и крупные хромосомные мутации; замену нуклеотида внутри гена в микроскоп увидеть нельзя.", "d": {"1": "Биохимический метод легко выявляет избыток фенилаланина в крови и моче новорождённого.", "2": "Секвенирование напрямую находит нуклеотидную замену в гене фермента.", "3": "Генеалогический метод позволяет установить аутосомно-рецессивный тип наследования болезни в семье."}}, "pair": {"type": "one", "cases": [["Случай А", "У новорождённого взяли каплю крови и обнаружили повышенную концентрацию фенилаланина."], ["Случай Б", "Лейкоциты крови обработали колхицином, окрасили и под микроскопом насчитали 47 хромосом (три 21-е хромосомы)."]], "q": "Какие методы применены в случаях А и Б?", "o": ["А — биохимический, Б — цитогенетический", "А — цитогенетический, Б — биохимический", "А — молекулярно-генетический, Б — гибридологический", "А — популяционно-статистический, Б — генеалогический"], "a": 0, "ex": "Определение концентрации вещества/активности фермента в крови — биохимический метод; подсчёт и анализ хромосом под микроскопом на метафазе — цитогенетический метод.", "d": {"1": "Методы перепутаны: хромосомы смотрят цитогенетическим методом, а химический состав крови — биохимическим.", "2": "Гибридологический метод (скрещивание) к человеку не применяется.", "3": "Оба исследования проведены у одного пациента, а не на родословной или популяции."}}, "fade": {"q": "Выстрой логику выбора метода и этапов кариотипирования:", "steps": ["1. Для изучения числа и структуры хромосом клетки обрабатывают {колхицином|адреналином|инсулином}, чтобы остановить деление на стадии {метафазы|интерфазы|телофазы} митоза.", "2. Чтобы оценить долю влияния среды и генотипа на рост и интеллект, применяют {близнецовый|генеалогический|гибридологический} метод.", "3. Определение точной последовательности нуклеотидов ДНК в № 1 КИМ называют {секвенированием|кариотипированием|центрифугированием}."], "why": "В метафазе хромосомы максимально спирализованы и видны в микроскоп. Близнецовый метод — единственный, разделяющий вклад среды и генотипа."}, "bug": {"q": "Найди ошибочное утверждение в описании методов генетики человека:", "steps": ["Гибридологический метод не применяют к человеку из-за этических ограничений, малого числа потомков и долгой смены поколений.", "Однояйцевые близнецы развиваются из одной зиготы, имеют одинаковый генотип и всегда одного пола.", "Цитогенетический метод позволяет диагностировать гемофилию и дальтонизм по кариограмме метафазных хромосом.", "Популяционно-статистический метод изучает частоты аллелей и генотипов в популяциях с помощью закона Харди–Вайнберга."], "bad": 2, "fix": "Гемофилия и дальтонизм — генные (точковые) мутации, которые не видны на кариограмме; их выявляют молекулярно-генетическим (секвенированием), биохимическим (анализ свёртываемости) и генеалогическим методами.", "why": "Цитогенетический метод выявляет только геномные (47, +21; 47, XXY; 45, X0) и крупные хромосомные мутации (делеция 5p−)."}, "recall": {"q": "Перечисли 4 причины неприменимости гибридологического метода к человеку и 4 этапа кариотипирования.", "points": ["Неприменимость к человеку: этический запрет на направленные скрещивания; малое число потомков; поздняя половая зрелость и долгая смена поколений; сложный кариотип (46 хромосом).", "Этап 1 кариотипирования: взятие и культивирование клеток (лейкоцитов крови) со стимуляцией митоза.", "Этап 2: обработка колхицином для остановки митоза на стадии метафазы.", "Этап 3: фиксация, окрашивание и микрофотографирование хромосом.", "Этап 4: раскладка хромосом попарно по размеру и форме (составление кариограммы)."]}}, {"id": "modif", "name": "Модификации, норма реакции и вариационная кривая", "ref": "03", "idea": "Отличать модификации от наследственной изменчивости, различать узкую и широкую норму реакции, читать оси вариационной кривой и помнить, что сама норма реакции средой не меняется.", "pre": {"type": "one", "q": "Клон растения вырастили на ярком солнце и в тени: в тени площадь листьев увеличилась вдвое. Что произошло с нормой реакции этого растения?", "o": ["Норма реакции не изменилась — изменился только фенотип в её пределах", "Норма реакции расширилась в сторону крупных листьев", "Норма реакции сдвинулась вправо из-за мутации в клетках листа", "Норма реакции передалась семенам уже в изменённом виде"], "a": 0, "ex": "Норма реакции определяется генотипом. У клона генотип не менялся, поэтому изменилась лишь степень проявления признака (фенотип) в пределах прежней нормы реакции.", "d": {"1": "Среда не может расширить норму реакции — она лишь реализует один из её вариантов.", "2": "Увеличение площади листьев в тени — массовая адаптивная модификация, а не мутация.", "3": "Модификации не наследуются; на свету из семян снова вырастут световые листья."}}, "pair": {"type": "one", "cases": [["Случай А", "Корову перевели на богатый сочный корм, и суточный удой вырос с 12 до 22 литров."], ["Случай Б", "При том же улучшении корма жирность молока этой коровы осталась в пределах 3,8–4,0%."]], "q": "Какой вывод о норме реакции этих двух признаков верен для ЕГЭ?", "o": ["Удойность имеет широкую норму реакции, а жирность молока — узкую", "Оба признака имеют широкую норму реакции", "Удойность имеет узкую норму реакции, а жирность молока — широкую", "Жирность молока вообще не зависит от генотипа"], "a": 0, "ex": "Классическая пара ЕГЭ: количество молока (удойность) сильно зависит от условий кормления (широкая норма реакции), а процент жира жёстко контролируется генотипом породы (узкая норма реакции).", "d": {"1": "Жирность молока почти не колеблется при смене корма — это узкая норма реакции.", "2": "Перепутано наоборот: сильно меняется именно удойность.", "3": "Именно жёсткий контроль генотипа и делает норму реакции узкой."}}, "fade": {"q": "Разбери опыт с гималайским кроликом и вариационной кривой:", "steps": ["1. У гималайского кролика на выбритой спине под пакетом со льдом отрастает {чёрная|белая|рыжая} шерсть, так как фермент тирозиназа активен при {пониженной|повышенной|любой} температуре.", "2. Все клетки кожи одного кролика имеют {одинаковый|разный|гаплоидный} генотип, значит это {модификационная|мутационная|комбинативная} изменчивость.", "3. На вариационной кривой по горизонтальной оси X откладывают {значение признака (варианту v)|частоту встречаемости (p)|температуру среды}, а пик колокола приходится на {средние|минимальные|максимальные} значения."], "why": "При низкой температуре на ушах, носу, лапах и под льдом синтезируется меланин. Ось X кривой — всегда варианта v, ось Y — частота p."}, "bug": {"q": "Найди ошибку в рассуждении ученика о модификационной изменчивости:", "steps": ["Модификационная изменчивость носит групповой (массовый) и адекватный условиям среды характер.", "У стрелолиста на одном растении развиваются лентовидные подводные, округлые плавающие и стреловидные воздушные листья — это пример модификаций.", "Все модификационные изменения полностью обратимы при возвращении организма в исходные условия.", "Наследуется не сам модификационный признак, а норма реакции, заданная генотипом."], "bad": 2, "fix": "Многие модификации обратимы (загар, удой), но не все: например, искривление костей при рахите или форма кроны дерева на ветру необратимы, оставаясь при этом модификациями.", "why": "Главный критерий модификации — неизменность ДНК и ненаследуемость, а не обязательная обратимость."}, "recall": {"q": "Перечисли 5 основных характеристик модификационной изменчивости (как в критериях части 2 ЕГЭ) и 3 эталонных примера ЕГЭ.", "points": ["Затрагивает только фенотип, не изменяет генотип и не передаётся по наследству.", "Носит групповой (массовый) и определённый характер.", "Изменения носят постепенный характер в ходе онтогенеза.", "Зависит от условий среды, адекватна им и носит приспособительный характер.", "Происходит в пределах нормы реакции, обусловленной генотипом.", "Эталонные примеры ЕГЭ: гималайский (горностаевый) кролик, стрелолист (разнолистность), китайская примула (цвет цветков от температуры)."]}}, {"id": "comb", "name": "Комбинативная изменчивость и закон Вавилова", "ref": "04", "idea": "Называть все три цитологических источника комбинативной изменчивости с точными фазами мейоза и применять закон гомологических рядов Н. И. Вавилова в заданиях № 7 и № 26.", "pre": {"type": "one", "q": "Почему при бесполом (вегетативном) размножении НЕ возникает комбинативная изменчивость?", "o": ["Отсутствуют мейоз и оплодотворение, перетасовывающие аллели", "При бесполом размножении вообще невозможны мутации", "В соматических клетках нет гомологичных хромосом", "При митозе происходит кроссинговер, стирающий комбинации"], "a": 0, "ex": "Все три источника комбинативной изменчивости связаны с половым размножением: кроссинговер (профаза I мейоза), независимое расхождение хромосом (анафаза I мейоза) и случайное слияние гамет.", "d": {"1": "Соматические мутации при вегетативном размножении как раз возможны и передаются потомкам.", "2": "Диплоидные соматические клетки содержат пары гомологичных хромосом.", "3": "Кроссинговер в норме идёт в профазе I мейоза, а не в митозе."}}, "pair": {"type": "one", "cases": [["Случай А", "У пары кудрявых хомяков родился здоровый гладкошёрстный детёныш."], ["Случай Б", "В колонии бактерий на чашке Петри с антибиотиком у одной клетки внезапно возникла устойчивость к препарату."]], "q": "Какие виды изменчивости проиллюстрированы в случаях А и Б?", "o": ["А — комбинативная, Б — мутационная", "А — мутационная, Б — комбинативная", "А — модификационная, Б — мутационная", "А — комбинативная, Б — модификационная"], "a": 0, "ex": "В случае А рецессивные аллели родителей соединились в новой комбинации (aa) без появления новых генов — комбинативная изменчивость. В случае Б у одной клетки в группе внезапно возник новый признак — мутационная изменчивость.", "d": {"1": "У бактерий при делении нет мейоза и оплодотворения; появление устойчивости — случайная мутация.", "2": "Отсылка к признакам родителей (гладкошёрстный у кудрявых) указывает на расщепление аллелей — комбинативную изменчивость.", "3": "Антибиотик не «учит» бактерию быть устойчивой, а лишь отбирает случайных мутантов."}}, "fade": {"q": "Собери точный ответ на задание № 26 по закону гомологических рядов Н. И. Вавилова:", "steps": ["1. У мягкой пшеницы найдена безостая форма; существование такой же формы у ржи и ячменя можно предсказать по закону {гомологических рядов в наследственной изменчивости|независимого наследования|расщепления}, открытому {Н. И. Вавиловым|Г. Менделем|Т. Морганом}.", "2. Генетическая причина параллельных рядов: родственные виды произошли от общего предка и имеют набор {гомологичных генов|одинаковых кариотипов|одинаковых модификаций}.", "3. В медицине этот закон позволяет подбирать {животных-моделей наследственных болезней человека|антибиотики против вирусов|условия для модификаций}."], "why": "Три обязательных элемента для 3 баллов в № 26: название закона и автор (Н. И. Вавилов) → общее происхождение и гомологичные гены → практическое прогнозирование."}, "bug": {"q": "Найди ошибочный пункт в списке источников комбинативной изменчивости:", "steps": ["Кроссинговер (обмен участками между гомологичными хромосомами) в профазе I мейоза.", "Независимое расхождение негомологичных хромосом к полюсам клетки в анафазе I мейоза.", "Ошибки фермента ДНК-полимеразы при репликации ДНК в S-периоде интерфазы.", "Случайная встреча и слияние гамет при оплодотворении."], "bad": 2, "fix": "Ошибки репликации ДНК изменяют саму нуклеотидную последовательность гена — это источник мутационной (генной), а не комбинативной изменчивости.", "why": "Комбинативная изменчивость никогда не меняет структуру самих генов — она лишь перетасовывает уже существующие аллели."}, "recall": {"q": "Назови три источника комбинативной изменчивости с фазами и сформулируй закон гомологических рядов Н. И. Вавилова.", "points": ["1) Кроссинговер в профазе I мейоза.", "2) Независимое расхождение негомологичных хромосом в анафазе I мейоза (и хроматид в анафазе II после кроссинговера).", "3) Случайное слияние гамет при оплодотворении.", "Закон Н. И. Вавилова: генетически близкие виды и роды характеризуются сходными рядами наследственной изменчивости.", "Причина закона: происхождение от общего предка и наличие гомологичных генов, мутирующих сходным образом."]}}, {"id": "mut", "name": "Мутации, их классификация и мутагены", "ref": "05", "idea": "Безошибочно разносить генные, хромосомные и геномные мутации, объяснять сдвиг рамки считывания, действие колхицина и отличие полиплоидии от анеуплоидии.", "pre": {"type": "one", "q": "Почему выпадение одного нуклеотида в кодирующей части гена почти всегда опаснее, чем замена одного нуклеотида?", "o": ["Выпадение сдвигает рамку считывания и меняет все последующие триплеты и аминокислоты белка", "Замена нуклеотида вообще никогда не меняет структуру белка", "Выпадение нуклеотида меняет сразу число хромосом в кариотипе", "Замена нуклеотида происходит только в соматических клетках"], "a": 0, "ex": "При выпадении 1 нуклеотида (не кратно 3) сдвигается рамка считывания от места мутации до конца гена. А замена затрагивает максимум один кодон и из-за вырожденности кода может вообще не изменить аминокислоту.", "d": {"1": "Замена может изменить аминокислоту (как при серповидноклеточной анемии) или создать стоп-кодон.", "2": "Изменение числа хромосом — геномная мутация, а выпадение одного нуклеотида — генная.", "3": "Замены возникают и в половых, и в соматических клетках."}}, "pair": {"type": "one", "cases": [["Случай А", "У проростков ржи после обработки колхицином число хромосом выросло с 2n = 14 до 4n = 28."], ["Случай Б", "У ребёнка в соматических клетках обнаружено 45 хромосом (45, X0 — отсутствует одна X-хромосома)."]], "q": "К каким видам геномных мутаций относятся случаи А и Б?", "o": ["А — полиплоидия, Б — анеуплоидия (моносомия)", "А — анеуплоидия, Б — полиплоидия", "А — полиплоидия, Б — хромосомная делеция", "А — дупликация, Б — анеуплоидия"], "a": 0, "ex": "Кратное увеличение гаплоидного набора (2n → 4n) — полиплоидия. Некратное изменение числа хромосом (как +1, так и −1, то есть 2n−1 = 45) — анеуплоидия (моносомия).", "d": {"1": "Перепутаны определения: полиплоидия всегда кратна n, анеуплоидия — некратна.", "2": "В случае Б утрачена целая хромосома (45 вместо 46), а не её участок — это геномная мутация.", "3": "Дупликация — удвоение участка одной хромосомы, а не всего набора хромосом."}}, "fade": {"q": "Восстанови цепочку действия колхицина (для № 8 и № 24–26 КИМ):", "steps": ["1. В S-периоде интерфазы происходит {репликация ДНК|кроссинговер|цитокинез}, и набор клетки становится 2n4c.", "2. Химический мутаген колхицин разрушает {микротрубочки веретена деления|ядерную оболочку|рибосомы}.", "3. В анафазе хромосомы {не расходятся к полюсам|обмениваются участками|разрываются на фрагменты}, митоз прерывается.", "4. Образуется клетка с кратно увеличенным набором 4n — возникает геномная мутация ({полиплоидия|анеуплоидия|транслокация})."], "why": "У растений полиплоидия часто полезна (крупнее плоды, выше урожайность), а у животных почти всегда летальна из-за нарушения хромосомного определения пола и сложного эмбриогенеза."}, "bug": {"q": "Найди ошибку в утверждениях о классификации мутаций:", "steps": ["Транслокация — это перенос участка хромосомы на негомологичную хромосому.", "Анеуплоидия — это исключительно увеличение числа хромосом на одну или две (трисомия).", "Цитоплазматические мутации (в ДНК митохондрий и хлоропластов) наследуются по материнской линии.", "Адаптивное значение одной и той же мутации относительно и зависит от условий среды."], "bad": 1, "fix": "Анеуплоидия (гетероплоидия) — это любое некратное гаплоидному набору изменение числа хромосом: как увеличение (2n+1 — трисомия), так и уменьшение (2n−1 — моносомия, 2n−2 — нуллисомия).", "why": "Синдром Шерешевского–Тёрнера (45, X0) — классический пример анеуплоидии с уменьшением числа хромосом."}, "recall": {"q": "Назови 4 вида хромосомных перестроек и 3 группы мутагенов с примерами.", "points": ["Делеция — утрата участка хромосомы (концевого — дефишенси).", "Дупликация — удвоение (повтор) участка хромосомы.", "Инверсия — поворот участка хромосомы на 180°.", "Транслокация — перенос/обмен участками между негомологичными хромосомами.", "Мутагены: физические (рентген, гамма-лучи, УФ, температура), химические (колхицин, нитриты, бензпирен, пестициды), биологические (вирусы, токсины бактерий и грибов)."]}}, {"id": "diseases", "name": "Кариотип человека и наследственные болезни", "ref": "06", "idea": "Различать генные, хромосомные и геномные болезни человека, безошибочно читать кариограммы (47, +21; 47, XXY; 45, X0; 47, XYY) и объяснять механизм нерасхождения в мейозе.", "pre": {"type": "one", "q": "Какой кариотип соответствует синдрому Клайнфельтера?", "o": ["47, XXY", "47, XYY", "45, X0", "46, 5p−"], "a": 0, "ex": "Синдром Клайнфельтера — это наличие лишней X-хромосомы у мужчин (47, XXY, реже XXXY). Кариотип 47, XYY — это отдельный синдром Якобса!", "d": {"1": "47, XYY — это синдром Якобса (лишняя Y-хромосома), а не Клайнфельтера.", "2": "45, X0 — это синдром Шерешевского–Тёрнера (моносомия по X у женщин).", "3": "46, 5p− — делеция короткого плеча 5-й хромосомы (синдром «кошачьего крика»)."}}, "pair": {"type": "one", "cases": [["Случай А", "У новорождённого 47 хромосом за счёт лишней 21-й аутосомы (синдром Дауна)."], ["Случай Б", "У новорождённого 46 хромосом, но утрачен фрагмент короткого плеча 5-й хромосомы (синдром «кошачьего крика»)."]], "q": "Как классифицируют эти мутации на ЕГЭ по биологии?", "o": ["А — геномная (трисомия), Б — хромосомная (делеция)", "Обе — хромосомные мутации", "А — хромосомная, Б — генная", "Обе — геномные мутации"], "a": 0, "ex": "В медицине обе относят к «хромосомным болезням», но в классификации мутаций ЕГЭ синдром Дауна меняет число хромосом (геномная мутация), а синдром «кошачьего крика» меняет структуру 5-й хромосомы при сохранении числа 46 (хромосомная делеция).", "d": {"1": "На ЕГЭ строго разводят геномные (число хромосом) и хромосомные (структура хромосомы) мутации.", "2": "Утрата целого фрагмента хромосомы с множеством генов — хромосомная, а не генная мутация.", "3": "При синдроме «кошачьего крика» число хромосом остаётся нормальным (46)."}}, "fade": {"q": "Объясни происхождение зиготы с синдромом Клайнфельтера (47, XXY) или Шерешевского–Тёрнера (45, X0):", "steps": ["1. В норме соматическая клетка человека содержит {46|44|23} хромосом: {44|46|22} аутосомы и 2 половые хромосомы.", "2. Из-за {нерасхождения половых хромосом в мейозе|ошибки репликации ДНК|кроссинговера в профазе I} образуются аномальные гаметы с набором {n+1 = 24 и n−1 = 22|2n = 46 и n = 23|n+2 = 25 и n−2 = 21}.", "3. Слияние гаметы (22А + XX) или (22А + XY) с нормальной гаметой даёт зиготу {47, XXY (синдром Клайнфельтера)|47, XYY (синдром Якобса)|45, X0 (синдром Тёрнера)}, а слияние гаметы (22А + 0) с нормальной (22А + X) даёт {45, X0 (синдром Шерешевского–Тёрнера)|47, XXX|47, +21}."], "why": "Ключевая формула части 2: нерасхождение хромосом в мейозе → образование аномальной гаметы (с лишней или недостающей хромосомой) → слияние с нормальной гаметой → аномальная зигота."}, "bug": {"q": "Найди биологическую ошибку в характеристике наследственных болезней человека:", "steps": ["Фенилкетонурия, альбинизм и муковисцидоз — аутосомно-рецессивные генные заболевания.", "Гемофилия, дальтонизм и миодистрофия Дюшенна наследуются сцепленно с X-хромосомой рецессивно.", "Галактоземия вызвана отсутствием фермента, расщепляющего дисахарид лактозу, и идентична лактазной недостаточности.", "Серповидноклеточная анемия вызвана точковой заменой нуклеотида в гене β-цепи гемоглобина; гетерозиготы устойчивы к малярии."], "bad": 2, "fix": "При галактоземии нарушен обмен моносахарида галактозы (нет фермента её превращения), а нарушение расщепления лактозы — это лактазная недостаточность.", "why": "Это одна из самых частых неточностей в школьных конспектах: галактоземия поражает печень, глаза и мозг именно из-за накопления галактозы."}, "recall": {"q": "Назови кариотип и тип мутации для 5 синдромов: Дауна, Патау, Эдвардса, Клайнфельтера, Шерешевского–Тёрнера и «кошачьего крика».", "points": ["Синдром Дауна: 47, +21 — геномная (трисомия по 21-й аутосоме).", "Синдром Патау: 47, +13 — геномная (трисомия по 13-й); Эдвардса: 47, +18 — геномная (трисомия по 18-й).", "Синдром Клайнфельтера: 47, XXY (мужчины) — геномная (анеуплоидия по половым хромосомам).", "Синдром Шерешевского–Тёрнера: 45, X0 (женщины) — геномная (моносомия по X-хромосоме).", "Синдром «кошачьего крика»: 46, 5p− — хромосомная (делеция короткого плеча 5-й хромосомы)."]}}, {"id": "medgen", "name": "Медицинская генетика, стволовые клетки и эксперимент № 22–23", "ref": "07", "idea": "Объяснять профилактику, скрининг и диетотерапию ФКУ, вред близкородственных браков, уровни потентности стволовых клеток и правила постановки эксперимента в № 22–23.", "pre": {"type": "one", "q": "Как специальная диета без фенилаланина предотвращает умственную отсталость при фенилкетонурии?", "o": ["Не исправляет мутантный ген, но убирает из пищи субстрат, не давая накапливаться токсичному метаболиту", "Исправляет точковую мутацию в клетках печени ребёнка", "Заменяет аутосомно-рецессивный аллель на доминантный", "Переводит генную мутацию в модификационную, чтобы она исчезла у детей"], "a": 0, "ex": "Диетотерапия — пример коррекции фенотипа: генотип (aa) остаётся прежним, но без избытка фенилаланина в пище не образуется токсичная фенилпировиноградная кислота.", "d": {"1": "Диета не редактирует ДНК — генотип человека не меняется.", "2": "Аллели в генотипе остаются рецессивными.", "3": "Мутантный аллель сохраняется в половых клетках и может передаться потомству."}}, "pair": {"type": "one", "cases": [["Случай А", "Клетка способна дать начало любому типу клеток организма И внезародышевым оболочкам (плаценте) — например, зигота."], ["Случай Б", "Эмбриональная стволовая клетка способна дать все ткани самого тела, но уже не может сформировать плаценту."]], "q": "Какие уровни потентности описаны в случаях А и Б?", "o": ["А — тотипотентность, Б — плюрипотентность", "А — плюрипотентность, Б — мультипотентность", "А — мультипотентность, Б — унипотентность", "А — тотипотентность, Б — унипотентность"], "a": 0, "ex": "Тотипотентные клетки (зигота, первые бластомеры) дают целый организм + плаценту; плюрипотентные (ЭСК, iPS) — любые ткани тела без внезародышевых оболочек.", "d": {"1": "Мультипотентные (например, клетки красного костного мозга) дают лишь ткани в пределах одного семейства (все клетки крови).", "2": "Унипотентные дают только один тип клеток (например, сперматогонии).", "3": "Эмбриональные стволовые клетки плюрипотентны, а не унипотентны."}}, "fade": {"q": "Собери эталонный ответ на № 22 КИМ (эксперимент по действию рентгеновского излучения на мышей):", "steps": ["1. Нулевая гипотеза: частота возникновения хромосомных аномалий {не зависит от дозы рентгеновского излучения|прямо пропорциональна дозе излучения|зависит только от возраста мышей}.", "2. Использование нескольких мышей в каждой группе снижает влияние {индивидуальной изменчивости|мутагена|температуры} и повышает {достоверность результатов|скорость митоза|размер выборки до одного животного}.", "3. Разница в возрасте исказит опыт, так как чувствительность к облучению в разном возрасте отличается, и {зависимость между дозой и частотой аномалий не удастся установить в явном виде|нулевая гипотеза автоматически подтвердится|мыши перестанут делиться митозом}."], "why": "Обязательная связка ФИПИ в № 22: указать, как посторонний фактор влияет на измеряемый показатель, + вывод «зависимость между X и Y не удастся установить в явном виде»."}, "bug": {"q": "Найди ошибочный пункт в разборе медицинской генетики и стволовых клеток:", "steps": ["Близкородственные браки повышают риск рождения больных детей, так как редкие рецессивные мутации от общих предков чаще переходят в гомозиготное состояние (aa).", "Амниоцентез и биопсия хориона позволяют провести кариотипирование плода до рождения (пренатальная диагностика).", "Собственные (аутологичные) стволовые клетки взрослого вызывают более сильное иммунное отторжение, чем чужие эмбриональные стволовые клетки.", "Неонатальный скрининг (анализ крови из пятки новорождённого) выявляет фенилкетонурию и галактоземию в первые дни жизни."], "bad": 2, "fix": "Наоборот: собственные (аутологичные) стволовые клетки генетически идентичны пациенту, поэтому НЕ вызывают иммунного отторжения (и не требуют разрушения эмбриона).", "why": "Отсутствие иммунного отторжения и этических проблем — два главных преимущества аутологичных и iPS-клеток в заданиях № 26."}, "recall": {"q": "Назови 2 главных свойства стволовых клеток, 4 уровня их потентности и объясни вред близкородственных браков.", "points": ["Два свойства стволовых клеток: способность к самообновлению (делению митозом) и способность к дифференцировке в специализированные клетки.", "Четыре уровня потентности: тотипотентные (зигота) → плюрипотентные (ЭСК) → мультипотентные (костный мозг) → унипотентные (миосателлиты, сперматогонии).", "Вред близкородственных браков: родственники унаследовали одинаковые редкие рецессивные мутации от общих предков.", "При браке двух гетерозиготных носителей (Aa × Aa) рецессивные аллели с вероятностью 25% переходят в гомозиготное состояние (aa) и проявляются болезнью."]}}], "figs": {"modifikacii-primery": {"sk": "modif", "ref": "03.10", "n": 5, "nm": 6, "gen": true}, "variacionnyj-ryad-listev": {"sk": "modif", "ref": "03.16", "n": 5, "nm": 6, "gen": true}, "poliploidiya-rasteniya": {"sk": "mut", "ref": "05.20", "n": 5, "gen": true}, "serpovidnye-eritrocity": {"sk": "diseases", "ref": "06.12", "n": 5, "gen": true}, "kariotip-trisomiya-21": {"sk": "diseases", "ref": "06.18", "n": 5, "gen": true}}, "tab": [{"id": "t_terms", "t": "Пять базовых терминов генетики", "k": "Термин", "km": "термином генетики", "ref": "01.15", "n": 6, "lv3": ["Геном", "Кариотип", "Генофонд"], "cols": [{"t": "Определение", "sk": "terms", "n": 6, "q": "Что описывает понятие «{x}»?", "m": "его определением"}, {"t": "Уровень организации", "sk": "terms", "n": 6, "q": "Какому уровню организации соответствует понятие «{x}»?", "m": "уровнем организации", "mq": "Выберите {k} термина, относящихся к уровню «{v}»:"}], "rows": [["Генотип", "Совокупность всех генов отдельной особи", "Одна особь"], ["Фенотип", "Совокупность всех внешних и внутренних признаков организма", "Одна особь"], ["Геном", "Совокупность всех генов гаплоидного набора хромосом вида (n)", "Вид (гаплоидный набор n)"], ["Кариотип", "Число, форма и размеры хромосом соматической клетки вида (2n)", "Вид (диплоидная клетка 2n)"], ["Генофонд", "Совокупность всех генов (аллелей) всех особей популяции", "Популяция"]], "rw": {"Геном": "Гаплоидный набор генов вида (у человека — гены 23 хромосом).", "Кариотип": "Морфология и число хромосом в диплоидной соматической клетке вида (2n = 46).", "Генофонд": "Генетический запас всей популяции, а не отдельной особи."}}, {"id": "t_methods", "t": "Методы генетики человека", "k": "Метод", "km": "методом генетики", "ref": "02.7", "n": 20, "lv3": ["Цитогенетический", "Биохимический", "Молекулярно-генетический (секвенирование)", "Популяционно-статистический"], "cols": [{"t": "Главная задача / объект", "sk": "methods", "n": 20, "q": "Что позволяет установить {x} метод?", "m": "его задачей"}, {"t": "Применимость к человеку / масштаб", "sk": "methods", "n": 6, "q": "К какой категории относится {x} метод?", "m": "категорией применения", "mq": "Выберите {k} метода, относящихся к категории «{v}»:"}], "rows": [["Гибридологический", "Скрещивание организмов и количественный анализ расщепления у потомства", "Неприменим к человеку (модельные объекты)"], ["Генеалогический", "Анализ родословных для определения типа наследования признака в семье", "Анализ наследования в семье / популяции"], ["Близнецовый", "Оценка доли влияния генотипа и среды на признак у моно- и дизиготных близнецов", "Оценка роли среды и генотипа"], ["Цитогенетический", "Микроскопия метафазных хромосом для выявления геномных и хромосомных мутаций", "Диагностика хромосомных и геномных болезней"], ["Биохимический", "Анализ ферментов и метаболитов в крови/моче для выявления генных болезней обмена", "Диагностика генных мутаций"], ["Молекулярно-генетический (секвенирование)", "Прямое определение последовательности нуклеотидов ДНК и поиск точковых мутаций", "Диагностика генных мутаций"], ["Популяционно-статистический", "Изучение частот аллелей и генотипов в больших группах людей (Харди–Вайнберг)", "Анализ наследования в семье / популяции"]], "rw": {"Цитогенетический": "Видит только число и структуру целых хромосом (Даун, Клайнфельтер, «кошачий крик»), но НЕ видит точковые генные мутации.", "Биохимический": "Выявляет фенилкетонурию и галактоземию по избытку метаболита или отсутствию фермента.", "Молекулярно-генетический (секвенирование)": "Находит точковые замены в ДНК даже у здоровых гетерозиготных носителей."}}, {"id": "t_norm", "t": "Норма реакции и виды изменчивости", "k": "Пример / признак", "km": "примером признака", "ref": "03.8", "n": 6, "lv3": ["Жирность молока коров", "Удойность коров", "Окраска шерсти гималайского кролика на холоде", "Рождение гладкошёрстного хомяка у кудрявых родителей", "Возникновение устойчивости у одной бактерии к антибиотику"], "cols": [{"t": "Категория", "sk": "modif", "n": 6, "q": "К какой категории изменчивости / нормы реакции относится пример: «{x}»?", "m": "категорией", "mq": "Выберите {k} примера, относящихся к категории «{v}»:"}], "rows": [["Удойность коров", "Широкая норма реакции (модификационная)"], ["Масса тела и рост человека", "Широкая норма реакции (модификационная)"], ["Размер (площадь) листьев на одном дереве", "Широкая норма реакции (модификационная)"], ["Окраска шерсти гималайского кролика на холоде", "Широкая норма реакции (модификационная)"], ["Жирность молока коров", "Узкая норма реакции"], ["Размер сердца и мозга человека", "Узкая норма реакции"], ["Группа крови и форма цветка", "Узкая норма реакции"], ["Рождение гладкошёрстного хомяка у кудрявых родителей", "Комбинативная изменчивость"], ["Разное сочетание цвета глаз и формы носа у брата и сестры", "Комбинативная изменчивость"], ["Возникновение устойчивости у одной бактерии к антибиотику", "Мутационная изменчивость"], ["Рождение альбиноса у пары чёрных ворон", "Мутационная изменчивость"]], "rw": {"Жирность молока коров": "Классическая ловушка ЕГЭ: удойность — широкая норма реакции, а жирность — узкая.", "Рождение гладкошёрстного хомяка у кудрявых родителей": "Отсылка к родителям (не болезнь) — новое сочетание аллелей (комбинативная изменчивость).", "Рождение альбиноса у пары чёрных ворон": "Альбинизм — рецессивная генная мутация (мутационная изменчивость)."}}, {"id": "t_mut", "t": "Классификация мутаций по уровню организации", "k": "Мутация / явление", "km": "примером мутации", "ref": "05.8", "n": 6, "lv3": ["Выпадение одного нуклеотида в цепи ДНК", "Утрата фрагмента короткого плеча 5-й хромосомы", "Перенос участка хромосомы на негомологичную хромосому", "Утрата одной X-хромосомы (45, X0)"], "cols": [{"t": "Тип мутации", "sk": "mut", "n": 6, "q": "К какому типу мутаций относится: «{x}»?", "m": "типом мутации", "mq": "Выберите {k} примера, относящихся к категории «{v}»:"}], "rows": [["Замена одного нуклеотида в кодирующей области гена", "Генная (точковая)"], ["Выпадение одного нуклеотида в цепи ДНК", "Генная (точковая)"], ["Вставка двух нуклеотидов (сдвиг рамки считывания)", "Генная (точковая)"], ["Утрата фрагмента короткого плеча 5-й хромосомы", "Хромосомная (перестройка)"], ["Удвоение участка хромосомы (дупликация)", "Хромосомная (перестройка)"], ["Поворот участка хромосомы на 180° (инверсия)", "Хромосомная (перестройка)"], ["Перенос участка хромосомы на негомологичную хромосому", "Хромосомная (перестройка)"], ["Кратное увеличение хромосом (2n → 4n) под действием колхицина", "Геномная (изменение числа хромосом)"], ["Появление лишней 21-й хромосомы (47, +21)", "Геномная (изменение числа хромосом)"], ["Утрата одной X-хромосомы (45, X0)", "Геномная (изменение числа хромосом)"]], "rw": {"Выпадение одного нуклеотида в цепи ДНК": "Делеция одного нуклеотида — генная мутация (не путай с хромосомной делецией участка!).", "Утрата фрагмента короткого плеча 5-й хромосомы": "Синдром «кошачьего крика»: число хромосом осталось 46, изменилась структура хромосомы.", "Утрата одной X-хромосомы (45, X0)": "Моносомия — разновидность анеуплоидии (геномная мутация)."}}, {"id": "t_dis", "t": "Наследственные заболевания человека", "k": "Заболевание", "km": "наследственным заболеванием", "ref": "06.10", "n": 6, "lv3": ["Синдром «кошачьего крика»", "Синдром Клайнфельтера (47, XXY)", "Синдром Шерешевского–Тёрнера (45, X0)", "Синдром Якобса (47, XYY)", "Галактоземия", "Серповидноклеточная анемия"], "cols": [{"t": "Тип мутации (для ЕГЭ)", "sk": "diseases", "n": 6, "q": "Каким типом мутации вызвано заболевание «{x}»?", "m": "типом мутации", "mq": "Выберите {k} заболевания, вызванных мутацией типа «{v}»:"}, {"t": "Основной метод диагностики", "sk": "diseases", "n": 20, "q": "Какой метод является ведущим для диагностики заболевания «{x}»?", "m": "методом диагностики", "mq": "Выберите {k} заболевания, для диагностики которых подходит «{v}»:"}], "rows": [["Фенилкетонурия (ФКУ)", "Генная (аутосомно-рецессивная)", "Биохимический / молекулярно-генетический"], ["Галактоземия", "Генная (аутосомно-рецессивная)", "Биохимический / молекулярно-генетический"], ["Альбинизм", "Генная (аутосомно-рецессивная)", "Биохимический / молекулярно-генетический"], ["Серповидноклеточная анемия", "Генная (точковая замена в β-цепи Hb)", "Биохимический / молекулярно-генетический"], ["Гемофилия", "Генная (X-сцепленная рецессивная)", "Биохимический / молекулярно-генетический"], ["Дальтонизм", "Генная (X-сцепленная рецессивная)", "Биохимический / молекулярно-генетический"], ["Синдром Дауна (47, +21)", "Геномная (анеуплоидия)", "Цитогенетический (кариотипирование)"], ["Синдром Клайнфельтера (47, XXY)", "Геномная (анеуплоидия)", "Цитогенетический (кариотипирование)"], ["Синдром Шерешевского–Тёрнера (45, X0)", "Геномная (анеуплоидия)", "Цитогенетический (кариотипирование)"], ["Синдром Якобса (47, XYY)", "Геномная (анеуплоидия)", "Цитогенетический (кариотипирование)"], ["Синдром Патау (47, +13)", "Геномная (анеуплоидия)", "Цитогенетический (кариотипирование)"], ["Синдром «кошачьего крика»", "Хромосомная (делеция 5p−)", "Цитогенетический (кариотипирование)"]], "rw": {"Синдром «кошачьего крика»": "Единственный частый в ЕГЭ синдром, вызванный именно хромосомной мутацией (делецией участка 5-й хромосомы при 2n = 46).", "Синдром Якобса (47, XYY)": "Лишняя Y-хромосома у мужчин — НЕ путай с синдромом Клайнфельтера (47, XXY)!", "Галактоземия": "Дефицит фермента обмена моносахарида галактозы (не лактозы)."}}, {"id": "t_stem", "t": "Уровни потентности стволовых клеток", "k": "Тип стволовых клеток", "km": "типом стволовых клеток", "ref": "07.10", "n": 6, "lv3": ["Тотипотентные", "Плюрипотентные", "Мультипотентные", "Унипотентные"], "cols": [{"t": "Возможности дифференцировки", "sk": "medgen", "n": 6, "q": "Что способны образовать {x} стволовые клетки?", "m": "их возможностями"}, {"t": "Пример клеток", "sk": "medgen", "n": 6, "q": "Какие клетки являются примером типа «{x}»?", "m": "примером клеток"}], "rows": [["Тотипотентные", "Целый организм, включая внезародышевые оболочки (плаценту)", "Зигота и первые бластомеры"], ["Плюрипотентные", "Любые ткани тела (все 3 зародышевых листка), но без плаценты", "Эмбриональные стволовые клетки (ЭСК) и iPS-клетки"], ["Мультипотентные", "Несколько типов клеток в пределах одной ткани/системы", "Кроветворные клетки красного костного мозга"], ["Унипотентные", "Только один специализированный тип клеток", "Миосателлиты мышц, сперматогонии"]], "rw": {"Тотипотентные": "Максимальная потентность: из одной клетки может развиться целый организм и плацента.", "Плюрипотентные": "ЭСК и индуцированные плюрипотентные клетки (iPS)."}}], "rx": [], "seq": [{"id": "sq_karyo", "sk": "methods", "ref": "02.17", "n": 8, "lvl": 3, "q": "Установите последовательность этапов проведения цитогенетического метода (кариотипирования) у человека:", "items": ["Забор крови и культивирование лейкоцитов со стимуляцией митоза", "Обработка делящихся клеток колхицином для остановки митоза на стадии метафазы", "Фиксация, окрашивание и микрофотографирование метафазных хромосом", "Группировка изображений хромосом попарно по размеру и форме (составление кариограммы)", "Выявление изменения числа или структуры хромосом (диагностика синдрома)"], "why": "Колхицин разрушает веретено деления и «замораживает» клетки в метафазе, когда хромосомы максимально спирализованы и лучше всего видны под микроскопом."}, {"id": "sq_var", "sk": "modif", "ref": "03.14", "n": 8, "lvl": 2, "q": "Установите последовательность действий при статистическом изучении модификационной изменчивости (по В. Иогансену):", "items": ["Сбор достаточно большой выборки однородных объектов (например, 100 листьев с одного дерева)", "Измерение значения изучаемого признака (длины) у каждого объекта выборки", "Расположение полученных значений (вариант v) в порядке возрастания — составление вариационного ряда", "Подсчёт частоты встречаемости (p) каждой варианты в выборке", "Построение вариационной кривой в координатах: ось X — варианта v, ось Y — частота p"], "why": "Сначала собирают и измеряют выборку, затем упорядочивают варианты в ряд, считают частоты и строят график (колоколообразную кривую)."}, {"id": "sq_comb", "sk": "comb", "ref": "04.4", "n": 8, "lvl": 2, "q": "Установите хронологическую последовательность событий, обеспечивающих комбинативную изменчивость при половом размножении:", "items": ["Конъюгация гомологичных хромосом в профазе I мейоза", "Кроссинговер — обмен гомологичными участками несестринских хроматид", "Выстраивание бивалентов по экватору клетки в метафазе I мейоза", "Независимое расхождение негомологичных двухроматидных хромосом к полюсам в анафазе I", "Завершение мейоза II и случайное слияние гаплоидных гамет при оплодотворении"], "why": "Три источника комбинативной изменчивости срабатывают строго по порядку: профаза I (кроссинговер) → анафаза I (независимое расхождение) → оплодотворение (слияние гамет)."}, {"id": "sq_colch", "sk": "mut", "ref": "05.18", "n": 8, "lvl": 3, "q": "Установите последовательность событий при получении тетраплоидного растения (4n) с помощью колхицина:", "items": ["Репликация ДНК в S-периоде интерфазы диплоидной клетки (набор 2n4c)", "Обработка проростков раствором колхицина и разрушение микротрубочек веретена деления", "Нерасхождение сестринских хроматид к полюсам в анафазе митоза", "Прерывание деления и формирование единого ядра с удвоенным набором хромосом (4n)", "Митотическое размножение тетраплоидных клеток и развитие более крупного растения"], "why": "Колхицин действует на веретено деления уже после удвоения ДНК, поэтому обе копии хромосом остаются в одной клетке (4n)."}, {"id": "sq_trisomy", "sk": "diseases", "ref": "06.21", "n": 8, "lvl": 3, "q": "Установите последовательность событий, приводящих к рождению ребёнка с синдромом Дауна (47, +21) у здоровых родителей:", "items": ["Вступление диплоидной половой клетки родителя (2n = 46) в мейоз", "Нерасхождение 21-й пары гомологичных хромосом в анафазе I (или хроматид в анафазе II) мейоза", "Формирование аномальной гаметы с двумя 21-ми хромосомами (n + 1 = 24)", "Слияние аномальной гаметы (24) с нормальной гаметой второго родителя (n = 23)", "Образование зиготы с трисомией по 21-й хромосоме (2n + 1 = 47) и развитие плода"], "why": "Причина трисомии-21 — случайное нерасхождение 21-й пары в мейозе у одного из родителей, дающее гамету n+1 = 24."}, {"id": "sq_stem", "sk": "medgen", "ref": "07.10", "n": 8, "lvl": 3, "q": "Расположите клетки в порядке УБЫВАНИЯ их потентности (от наибольших возможностей дифференцировки к наименьшим):", "items": ["Зигота (тотипотентная клетка)", "Эмбриональная стволовая клетка внутренней клеточной массы (плюрипотентная)", "Гемопоэтическая стволовая клетка красного костного мозга (мультипотентная)", "Миосателлит скелетной мышцы (унипотентная клетка)", "Зрелый дифференцированный эритроцит (не способна к делению)"], "why": "В ходе онтогенеза потентность клеток последовательно сужается: тотипотентная → плюрипотентная → мультипотентная → унипотентная → терминально дифференцированная."}], "facts": [{"id": "f_terms", "sk": "terms", "ref": "01.15", "n": 7, "lvl": 2, "t": "Основные понятия генетики", "s": [["Ген — участок молекулы ДНК, кодирующий первичную структуру одного полипептида или молекулу функциональной РНК.", "Ген — участок молекулы ДНК, который всегда кодирует исключительно один готовый сложный белок.", "Многие гены кодируют тРНК или рРНК, а сложные белки (например, гемоглобин) кодируются несколькими генами."], ["Аллельные гены располагаются в одинаковых локусах гомологичных хромосом и определяют альтернативные признаки.", "Аллельные гены располагаются в разных локусах негомологичных хромосом.", "Гены в разных локусах — неаллельные."], ["Геном — это совокупность всех генов гаплоидного набора хромосом данного биологического вида.", "Геном — это совокупность признаков хромосом диплоидной соматической клетки вида.", "Число, форма и размеры хромосом соматической клетки — это кариотип."], ["Генофонд описывает совокупность всех генов (аллелей) всех особей данной популяции.", "Генофонд описывает совокупность всех генов одной конкретной особи.", "Совокупность всех генов одной особи — это генотип."], ["При неполном доминировании у гетерозиготы Aa развивается промежуточный вариант признака.", "Доминантный признак всегда полностью подавляет рецессивный у гетерозиготы Aa.", "Полное подавление наблюдается только при полном доминировании."], ["Чистая линия — группа гомозиготных особей, не дающая расщепления в потомстве при самоопылении.", "Чистая линия — это гибрид первого поколения F_{1}, полученный от скрещивания контрастных сортов.", "Гибриды F_{1} от разных чистых линий гетерозиготны (Aa) и дают расщепление в F_{2}."]]}, {"id": "f_methods", "sk": "methods", "ref": "02.7", "n": 7, "lvl": 3, "t": "Методы генетики человека", "s": [["Цитогенетический метод позволяет диагностировать геномные (синдром Дауна) и крупные хромосомные мутации.", "Цитогенетический метод позволяет под световым микроскопом выявить точковую замену нуклеотида при фенилкетонурии.", "Точковые генные мутации в световой микроскоп не видны; их ищут биохимически или секвенированием."], ["Близнецовый метод позволяет оценить долю влияния генотипа и условий среды на развитие признака.", "Близнецовый метод позволяет определить точное число хромосом в кариотипе человека.", "Число хромосом определяет цитогенетический метод."], ["Однояйцевые близнецы развиваются из одной зиготы, генетически идентичны и всегда одного пола.", "Разнояйцевые близнецы развиваются из одной зиготы и имеют на 100% одинаковый генотип.", "Разнояйцевые (дизиготные) близнецы развиваются из двух разных яйцеклеток и имеют ~50% общих аллелей."], ["Биохимический метод выявляет генные болезни обмена веществ по активности ферментов и концентрации метаболитов в крови или моче.", "Биохимический метод заключается в составлении и анализе семейных родословных в ряде поколений.", "Составление родословных — это генеалогический метод."], ["Популяционно-статистический метод изучает частоты встречаемости аллелей и генотипов в популяциях людей.", "Гибридологический метод является основным способом изучения наследования заболеваний у человека.", "Гибридологический метод к человеку неприменим по этическим и биологическим причинам."], ["Секвенирование (молекулярно-генетический метод) позволяет установить точную последовательность нуклеотидов ДНК.", "Для кариотипирования клетки останавливают на стадии интерфазы, когда хромосомы деспирализованы.", "Для кариотипирования деление останавливают колхицином на стадии метафазы митоза."]]}, {"id": "f_modif", "sk": "modif", "ref": "03.4", "n": 7, "lvl": 2, "t": "Модификационная изменчивость и норма реакции", "s": [["Модификационная изменчивость затрагивает только фенотип, не изменяет ДНК и не передаётся по наследству.", "Модификационная изменчивость закрепляется в генотипе и передаётся семенному потомству.", "Модификации ненаследственны; передаётся только норма реакции."], ["Норма реакции обусловлена генотипом и не изменяется при переносе организма в другие условия среды.", "При выращивании клона растения в тени его норма реакции расширяется и сдвигается вправо.", "Меняется только фенотип в пределах прежней нормы реакции."], ["Удойность коров имеет широкую норму реакции, а жирность молока — узкую.", "Жирность молока коров имеет широкую норму реакции, а количество молока (удойность) — узкую.", "Наоборот: количество молока сильно зависит от корма, а процент жира жёстко задан породой."], ["Модификационная изменчивость носит групповой (массовый), определённый и приспособительный характер.", "Модификационная изменчивость всегда носит случайный, индивидуальный и ненаправленный характер.", "Случайной и индивидуальной является мутационная изменчивость."], ["На вариационной кривой по горизонтальной оси X откладывают значения признака (варианты), а по оси Y — частоту их встречаемости.", "На вариационной кривой максимум всегда приходится на минимальное или максимальное значение признака.", "Максимум колоколообразной кривой всегда приходится на средние значения признака."], ["Некоторые модификации (например, искривление костей при рахите) необратимы, но всё равно не передаются по наследству.", "Любое необратимое изменение фенотипа в ходе онтогенеза является мутацией.", "Критерий мутации — изменение ДНК, а не необратимость."]]}, {"id": "f_comb", "sk": "comb", "ref": "04.6", "n": 7, "lvl": 2, "t": "Комбинативная изменчивость и закон Вавилова", "s": [["Комбинативная изменчивость создаёт новые сочетания уже существующих аллелей без изменения структуры самих генов.", "Комбинативная изменчивость возникает вследствие изменения последовательности нуклеотидов в ДНК.", "Изменение последовательности нуклеотидов — это генная мутация."], ["Кроссинговер в профазе I мейоза и независимое расхождение хромосом в анафазе I являются источниками комбинативной изменчивости.", "Репликация ДНК в интерфазе и расхождение хроматид при митозе являются главными источниками комбинативной изменчивости.", "Митоз сохраняет исходную комбинацию аллелей."], ["Случайное слияние гамет при оплодотворении относится к источникам комбинативной изменчивости.", "Комбинативная изменчивость активно проявляется при вегетативном размножении растений черенками.", "При вегетативном размножении нет мейоза и оплодотворения."], ["Согласно закону гомологических рядов Н. И. Вавилова, генетически близкие виды и роды имеют сходные ряды наследственной изменчивости.", "Закон гомологических рядов сформулировал Грегор Мендель на основании опытов с горохом.", "Закон гомологических рядов открыл Н. И. Вавилов в 1920 году."], ["Причина параллельных рядов изменчивости у родственных видов — общее происхождение и наличие гомологичных генов.", "Причина закона Вавилова — одинаковые условия среды, вызывающие одинаковые модификации.", "Закон Вавилова описывает именно наследственную (мутационную) изменчивость."], ["Закон Вавилова используют в медицине для подбора животных-моделей наследственных болезней человека.", "Комбинативная изменчивость не имеет значения для эволюции, так как не создаёт разнообразия особей.", "Она создаёт огромное внутривидовое разнообразие — материал для естественного отбора."]]}, {"id": "f_mut", "sk": "mut", "ref": "05.18", "n": 7, "lvl": 3, "t": "Мутационная изменчивость и мутагены", "s": [["Выпадение или вставка 1–2 нуклеотидов вызывает сдвиг рамки считывания и искажает всю последующую часть белка.", "Замена одного нуклеотида всегда вызывает сдвиг рамки считывания.", "Замена затрагивает только один триплет и не сдвигает рамку."], ["Транслокация — хромосомная перестройка, при которой участок хромосомы переносится на негомологичную хромосому.", "Транслокация — это нормальный обмен участками между гомологичными хромосомами в профазе I мейоза.", "Обмен между гомологичными хромосомами — это кроссинговер."], ["Анеуплоидия включает как увеличение (2n+1), так и уменьшение (2n−1) числа отдельных хромосом.", "Анеуплоидия — это кратное гаплоидному набору увеличение числа хромосом (3n, 4n, 6n).", "Кратное увеличение набора — это полиплоидия."], ["Колхицин является химическим мутагеном, разрушающим микротрубочки веретена деления и вызывающим полиплоидию.", "Рентгеновское и ультрафиолетовое излучение относятся к химическим мутагенам.", "Рентген и УФ — физические мутагены."], ["Соматические мутации не передаются при половом размножении, но могут передаваться при вегетативном размножении.", "Соматические мутации никогда не передаются потомству ни при каком способе размножения.", "У растений соматическую мутацию на ветке можно закрепить черенкованием или прививкой."], ["Большинство мутаций рецессивны и сохраняются в гетерозиготах, образуя скрытый резерв наследственной изменчивости.", "Полезность или вредность мутации абсолютна и не зависит от условий обитания вида.", "Адаптивное значение мутации относительно (бескрылость полезна на ветреных островах)."]]}, {"id": "f_dis", "sk": "diseases", "ref": "06.16", "n": 7, "lvl": 3, "t": "Кариотип и наследственные болезни человека", "s": [["В нормальной соматической клетке человека 44 аутосомы и 2 половые хромосомы (46, XX или 46, XY).", "В нормальной яйцеклетке человека содержится 44 аутосомы и одна X-хромосома.", "В зрелой гамете человека гаплоидный набор: 22 аутосомы + 1 половая хромосома (всего 23)."], ["Синдром Клайнфельтера характеризуется кариотипом 47, XXY (лишняя X-хромосома у мужчин).", "Синдром Клайнфельтера характеризуется кариотипом 47, XYY.", "Кариотип 47, XYY — это самостоятельный синдром Якобса."], ["Синдром Шерешевского–Тёрнера (45, X0) — геномная мутация (моносомия по X-хромосоме у женщин).", "Синдром Шерешевского–Тёрнера (45, X0) встречается у мужчин и сопровождается наличием лишней Y-хромосомы.", "При 45, X0 отсутствует Y-хромосома — это женский кариотип с одной X-хромосомой."], ["Синдром «кошачьего крика» вызван хромосомной мутацией (делецией короткого плеча 5-й хромосомы при 2n = 46).", "Синдром «кошачьего крика» вызван трисомией по 5-й хромосоме (47 хромосом).", "Число хромосом при этом синдроме остаётся равным 46."], ["Галактоземия — аутосомно-рецессивная генная болезнь нарушения обмена моносахарида галактозы.", "Любое врождённое заболевание обязательно является наследственным и передаётся потомству.", "Врождённые пороки могут быть ненаследственными — вызванными тератогенами во время беременности."], ["Гемофилия и дальтонизм — рецессивные генные болезни, сцепленные с X-хромосомой.", "Синдром Дауна (47, +21) является примером генной (точковой) мутации.", "Синдром Дауна — геномная мутация (трисомия по 21-й аутосоме)."]]}, {"id": "f_medgen", "sk": "medgen", "ref": "07.11", "n": 7, "lvl": 3, "t": "Медицинская генетика и стволовые клетки", "s": [["Близкородственные браки повышают вероятность перехода редких рецессивных мутаций в гомозиготное состояние (aa).", "Близкородственные браки повышают частоту возникновения новых точковых мутаций в ДНК.", "Они не увеличивают частоту мутагенеза, а повышают шанс встречи двух одинаковых рецессивных аллелей."], ["Диета без фенилаланина при ФКУ корректирует фенотип, не изменяя мутантный генотип пациента.", "Ранняя диета при фенилкетонурии полностью исправляет мутантный ген в клетках организма.", "Генотип остаётся aa; диета лишь предотвращает накопление токсичного продукта обмена."], ["Стволовые клетки способны к самообновлению (делению митозом) и дифференцировке в специализированные клетки.", "Стволовые клетки — это терминально дифференцированные клетки, утратившие способность к делению.", "Недифференцированность и способность делиться — главные свойства стволовых клеток."], ["Зигота является тотипотентной клеткой, а эмбриональные стволовые клетки — плюрипотентными.", "Кроветворные клетки красного костного мозга являются тотипотентными и могут дать целый организм.", "Клетки костного мозга мультипотентны — они дают только клетки крови."], ["Аутологичные (собственные) стволовые клетки взрослого не вызывают иммунного отторжения при трансплантации.", "Пересадка собственных стволовых клеток пациента требует пожизненного подавления иммунитета.", "Иммуносупрессия нужна при пересадке чужих (донорских) клеток, а не собственных."], ["В биологическом эксперименте нулевая гипотеза предполагает отсутствие зависимости между независимой и зависимой переменными.", "В эксперименте увеличение числа подопытных организмов в группе увеличивает случайную погрешность измерений.", "Увеличение выборки снижает случайную ошибку и повышает достоверность результатов."]]}], "calc": [{"id": "c_poly", "sk": "mut", "ref": "05.18", "n": 5, "lvl": 2, "v": {"n0": [7, 8, 9, 10, 12, 14], "k": [3, 4, 6]}, "q": "В гаплоидном наборе хромосом (n) диплоидного растения содержится {=n0} хромосом. Сколько хромосом будет в соматической клетке полиплоида с плоидностью {=k}n?", "a": "n0 * k", "dp": 0, "unit": "хромосом", "ex": "При полиплоидии число хромосом кратно гаплоидному набору n: {=k} · {=n0} = {=n0*k} хромосом."}, {"id": "c_auto", "sk": "diseases", "ref": "06.5", "n": 5, "lvl": 2, "v": {"tot": [38, 40, 42, 46, 48, 54, 60, 78]}, "q": "В диплоидной соматической клетке млекопитающего содержится {=tot} хромосом (из них 2 половые). Сколько аутосом содержится в одной зрелой гамете (яйцеклетке или сперматозоиде) этого вида?", "a": "tot / 2 - 1", "dp": 0, "unit": "аутосом", "ex": "В гамете гаплоидный набор n = {=tot} / 2 = {=tot/2} хромосом, из них 1 половая. Значит, аутосом: {=tot/2} − 1 = {=tot/2-1}."}, {"id": "c_gamcomb", "sk": "comb", "ref": "04.6", "n": 5, "lvl": 3, "v": {"pairs": [3, 4, 5, 6, 7, 8]}, "q": "Диплоидный набор хромосом организма равен 2n = {=pairs*2} ({=pairs} пар гомологичных хромосом). Сколько генетически различных типов гамет может образоваться только за счёт независимого расхождения негомологичных хромосом в анафазе I мейоза (без учёта кроссинговера)?", "a": "2 ^ pairs", "dp": 0, "unit": "типов гамет", "ex": "По формуле независимого расхождения число комбинаций равно 2^n = 2^{=pairs} = {=2^pairs}."}, {"id": "c_nondisj", "sk": "diseases", "ref": "06.20", "n": 5, "lvl": 3, "v": {"n0": [19, 20, 21, 23, 24, 30]}, "q": "У млекопитающего гаплоидный набор n = {=n0}. В анафазе I мейоза не разошлась одна пара гомологичных хромосом, и образовавшаяся гамета с лишней хромосомой (n + 1) слилась с нормальной гаметой (n). Сколько хромосом окажется в зиготе (трисомике)?", "a": "2 * n0 + 1", "dp": 0, "unit": "хромосом", "ex": "Аномальная гамета несёт n + 1 = {=n0+1} хромосом, нормальная — {=n0}. В зиготе: ({=n0+1}) + {=n0} = {=2*n0+1} хромосом (2n + 1)."}, {"id": "c_normrange", "sk": "modif", "ref": "03.14", "n": 5, "lvl": 2, "v": {"vmin": [4, 5, 6, 8], "span": [5, 7, 9, 11]}, "q": "В вариационном ряду длины листьев одного дерева минимальная варианта составляет {=vmin} см, а максимальная — {=vmin+span} см. Чему равен размах изменчивости (ширина данного диапазона нормы реакции)?", "a": "span", "dp": 0, "unit": "см", "ex": "Размах вариационного ряда равен разности максимальной и минимальной вариант: {=vmin+span} − {=vmin} = {=span} см."}, {"id": "c_consang", "sk": "medgen", "ref": "07.5", "n": 5, "lvl": 3, "v": {"pairs": [40, 60, 80, 100, 120]}, "q": "В популяции зафиксировано {=pairs} браков, в каждом из которых оба супруга являются здоровыми гетерозиготными носителями аутосомно-рецессивного гена фенилкетонурии (Aa × Aa). Сколько процентов от всех рождённых в этих браках детей теоретически унаследуют заболевание (aa)?", "a": "25", "dp": 0, "unit": "%", "ex": "При скрещивании Aa × Aa расщепление по генотипу 1 AA : 2 Aa : 1 aa — вероятность гомозиготы aa равна 1/4 = 25% (независимо от числа семей)."}], "tasks": [{"id": "pdf_t1_heur", "src": "user", "type": "match", "sk": "modif", "ref": "03.4", "n": 6, "lvl": 3, "q": "Примени эвристику из материалов курса: установи соответствие между примером из формулировки КИМ и видом изменчивости.", "left": ["Изменение окраски зайца-беляка в зависимости от температуры среды", "Рождение альбиносов у пары чёрных ворон", "Рождение гладкошёрстного хомяка у кудрявых родителей", "Возникновение устойчивости у одной бактерии к определённому антибиотику в большой колонии"], "right": ["Модификационная изменчивость", "Комбинативная изменчивость", "Мутационная изменчивость"], "a": [0, 2, 1, 2], "ex": "Прямая зависимость от условий среды → модификационная; заболевание/альбинизм или появление нового признака у одной особи в группе → мутационная; отсылка к признакам родителей (не болезнь) → комбинативная."}, {"id": "pdf_t2_22", "src": "user", "type": "part2", "sk": "medgen", "ref": "07.15", "n": 22, "lvl": 3, "img": "topics/biology/osnovy-genetiki-izmenchivost/trainer_assets/pdf-xray-graph.png", "q": "Учёный исследовал, как рентгеновское излучение воздействует на домовую мышь (Mus musculus). В рамках эксперимента на протяжении 24 часов лабораторные грызуны получали облучение разных дозировок, после чего исследователь определял частоту возникновения хромосомных аномалий в клетках эпителиального слоя их роговицы. Результаты эксперимента показаны на графике.\n\nКакую нулевую гипотезу можно сформулировать перед постановкой эксперимента? Почему требуется подвергать облучению не одну, а сразу несколько мышей? Как разница в возрасте между мышами может исказить результаты эксперимента?\n\n*Нулевая гипотеза — принимаемое по умолчанию предположение о том, что не существует связи между двумя наблюдаемыми событиями, феноменами.*", "ideal": "1) Нулевая гипотеза: частота возникновения хромосомных аномалий (ИЛИ частота митозов с аберрациями) не зависит от дозы рентгеновского излучения.\n2) Использование нескольких мышей исключает (или снижает) влияние индивидуальной изменчивости на результат / повышает достоверность результатов / уменьшает погрешность измерений.\n3) Чувствительность к рентгеновскому облучению (ИЛИ частота возникновения хромосомных аномалий / митозов с аберрациями) в разном возрасте у мышей может отличаться.\n4) Зависимость между частотой возникновения хромосомных аномалий (ИЛИ частотой митозов с аберрациями) и дозой рентгеновского излучения не удастся установить в явном виде.", "crit": [["1) Нулевая гипотеза: частота хромосомных аномалий (митозов с аберрациями) не зависит от дозы рентгеновского излучения", 1], ["2) Использование нескольких мышей снижает влияние индивидуальной изменчивости / повышает достоверность / уменьшает погрешность", 1], ["3) Чувствительность к облучению (частота аномалий) в разном возрасте у мышей может отличаться", 1], ["4) Зависимость между частотой аномалий и дозой облучения не удастся установить в явном виде", 1]], "max": 3, "ex": "Шкала оценивания из материалов: 4 ЭО — 3 балла; 3 ЭО — 2 балла; 2 ЭО — 1 балл; остальное — 0 баллов."}, {"id": "pdf_t3_23", "src": "user", "type": "part2", "sk": "mut", "ref": "02.17", "n": 23, "lvl": 3, "img": "topics/biology/osnovy-genetiki-izmenchivost/trainer_assets/pdf-xray-graph.png", "q": "Учёный исследовал, как рентгеновское излучение воздействует на домовую мышь (Mus musculus). На протяжении 24 часов грызуны получали облучение разных дозировок, после чего исследователь определял частоту возникновения хромосомных аномалий в клетках эпителиального слоя их роговицы (см. график).\n\nКаким методом учёный выявлял хромосомные аномалии в клетках мышей? Укажите два визуальных признака изменений в хромосомах, которые могли помочь исследователю установить наличие аномалий. К какой категории мутагенов (по своей природе) можно причислить рентгеновское излучение? Приведите ещё один пример такого рода мутагена.", "ideal": "1) С помощью цитогенетического (ИЛИ цитологического) метода (ИЛИ метода кариотипирования).\n2) Изменение длины хромосом.\n3) Изменение формы хромосом (ИЛИ положения центромеры).\n4) Рентгеновское излучение относится к физическим мутагенам.\n5) Другой пример физического мутагена: ультрафиолетовое излучение ИЛИ радиоактивное (гамма-) излучение ИЛИ температура и т. д. (достаточно одного примера).", "crit": [["1) Назван цитогенетический (цитологический) метод / кариотипирование", 1], ["2) Визуальный признак 1: изменение длины хромосом", 1], ["3) Визуальный признак 2: изменение формы хромосом (или положения центромеры)", 1], ["4) Рентгеновское излучение отнесено к физическим мутагенам", 1], ["5) Приведён ещё один пример физического мутагена (УФ, гамма-/радиоактивное излучение, температура)", 1]], "max": 3, "ex": "Шкала оценивания из материалов: 5 ЭО — 3 балла; 4 ЭО — 2 балла; 3 ЭО — 1 балл; остальное — 0 баллов."}, {"id": "pdf_t4_24_xxy", "src": "user", "type": "part2", "sk": "diseases", "ref": "06.20", "n": 24, "lvl": 3, "img": "topics/biology/osnovy-genetiki-izmenchivost/trainer_assets/pdf-kariotip-xxy.png", "q": "Кариограмма — графическое изображение кариотипа (числа, формы и размеров хромосом). В медицинской генетике с помощью кариограммы диагностируют некоторые хромосомные и геномные мутации.\n\nРассмотрите кариограмму человека. Представителю какого пола она принадлежит и почему? Определите общее число хромосом, число аутосом и половых хромосом. На каком основании её можно использовать для иллюстрации примера синдрома Клайнфельтера? Укажите возможные причины появления данного синдрома с точки зрения формирования половых клеток и оплодотворения.", "ideal": "1) Данная кариограмма принадлежит представителю мужского пола (мужчине).\n2) Так как в 23-й паре хромосом видна Y-хромосома, внешне отличающаяся от X-хромосомы (меньше по размеру).\n3) Общее число хромосом — 47, число аутосом — 44, число половых хромосом — 3 (XXY).\n4) Кариограмма содержит аномалию: лишнюю X-хромосому (у мужчин, страдающих синдромом Клайнфельтера, обнаруживается одна или несколько лишних половых хромосом X).\n5) Нерасхождение хромосом (половых хромосом) в мейозе ИЛИ образование аномальной гаметы с лишней половой хромосомой.\n6) Слияние аномальной гаметы с нормальной гаметой ИЛИ образование зиготы с лишней половой хромосомой.", "crit": [["1) Указан мужской пол (мужчина)", 1], ["2) Пояснение: среди половых хромосом (23-я пара) присутствует Y-хромосома", 1], ["3) Общее число хромосом — 47, аутосом — 44, половых хромосом — 3 (XXY)", 1], ["4) Основание: наличие лишней X-хромосомы (синдром Клайнфельтера — лишние X при наличии Y)", 1], ["5) Причина в гаметогенезе: нерасхождение половых хромосом в мейозе / образование аномальной гаметы с лишней хромосомой", 1], ["6) Оплодотворение: слияние аномальной гаметы с нормальной / образование зиготы с лишней половой хромосомой", 1]], "max": 3, "ex": "Шкала оценивания из материалов: 6 ЭО — 3 балла; 4–5 ЭО — 2 балла; 3 ЭО — 1 балл. ВАЖНО: если пол человека определён неверно — 0 баллов!"}, {"id": "pdf_t5_24_x0", "src": "user", "type": "part2", "sk": "diseases", "ref": "06.20", "n": 24, "lvl": 3, "img": "topics/biology/osnovy-genetiki-izmenchivost/trainer_assets/pdf-kariotip-x0.png", "q": "Кариограмма — графическое изображение кариотипа (числа, формы и размеров хромосом). В медицинской генетике с помощью кариограммы диагностируют некоторые хромосомные и геномные мутации.\n\nРассмотрите кариограмму человека. Представителю какого пола она принадлежит? Ответ поясните. Определите общее число хромосом, число аутосом и половых хромосом. На основании чего можно утверждать, что это кариограмма человека с синдромом Шерешевского–Тёрнера? Укажите возможные причины появления данного синдрома с точки зрения формирования половых клеток и оплодотворения.", "ideal": "1) Данная кариограмма принадлежит представителю женского пола (женщине).\n2) Так как в 23-й паре хромосом видна одна X-хромосома из пары половых хромосом и отсутствует Y-хромосома.\n3) Общее число хромосом — 45, число аутосом — 44, число половых хромосом — 1 (X или X0).\n4) Кариограмма содержит аномалию: отсутствует одна половая хромосома X (у женщин с синдромом Шерешевского–Тёрнера обнаруживается полное отсутствие одной X-хромосомы — моносомия по X).\n5) Нерасхождение половых хромосом в мейозе ИЛИ образование аномальной гаметы с недостающей половой хромосомой (без половой хромосомы).\n6) Слияние аномальной гаметы с нормальной гаметой ИЛИ образование зиготы с недостающей половой хромосомой.", "crit": [["1) Указан женский пол (женщина)", 1], ["2) Пояснение: видна одна X-хромосома и отсутствует Y-хромосома", 1], ["3) Общее число хромосом — 45, аутосом — 44, половых хромосом — 1 (X / X0)", 1], ["4) Основание: отсутствует одна половая хромосома X (моносомия по X)", 1], ["5) Причина в гаметогенезе: нерасхождение половых хромосом в мейозе / образование аномальной гаметы без половой хромосомы", 1], ["6) Оплодотворение: слияние аномальной гаметы с нормальной / образование зиготы с недостающей половой хромосомой", 1]], "max": 3, "ex": "Шкала оценивания из материалов: 6 ЭО — 3 балла; 4–5 ЭО — 2 балла; 3 ЭО — 1 балл. ВАЖНО: если пол человека определён неверно — 0 баллов!"}, {"id": "pdf_t6_24_rabbit", "src": "user", "type": "part2", "sk": "modif", "ref": "03.10", "n": 24, "lvl": 3, "img": "topics/biology/osnovy-genetiki-izmenchivost/trainer_assets/pdf-krolik-gornostaevyj.png", "q": "Кролики с горностаевой окраской рождаются полностью белыми. Однако из-за воздействия низкой температуры на определённые участки их тела мех начинает темнеть.\n\nУкажите вид изменчивости, к которому относится данное явление. Ответ поясните. Дайте ему характеристику. Какого цвета вырастет шерсть, если вместо льда (рисунок В) к побритому участку кожи приложить согревающий компресс?", "ideal": "1) Данное явление относится к модификационной (ненаследственной / фенотипической / определённой) изменчивости.\n2) Клетки кожи одного кролика, обеспечивающие образование пигмента, имеют одинаковый генотип (образованы митозом зиготы).\n3) Различный окрас шерсти возникает в ходе индивидуального развития (онтогенеза) животного из-за различных условий среды (различной температуры).\nХарактеристики модификационной изменчивости:\n4) Затрагивает только фенотип / не затрагивает генотип / не наследуется.\n5) Носит групповой (массовый) характер.\n6) Изменения носят постепенный характер.\n7) Изменения зависят от условий среды (адекватны условиям среды, носят приспособительный характер, происходят в пределах нормы реакции).\n8) Если вместо льда к побритому участку кожи приложить согревающий компресс, то вырастет белая шерсть.", "crit": [["1) Указана модификационная (ненаследственная / фенотипическая / определённая) изменчивость", 1], ["2) Пояснение 1: клетки кожи одного кролика имеют одинаковый генотип (образованы митозом)", 1], ["3) Пояснение 2: различный окрас возникает в онтогенезе из-за разных условий среды (температуры)", 1], ["4) Характеристика: затрагивает только фенотип, не меняет генотип, не наследуется", 1], ["5) Характеристика: носит групповой (массовый) характер", 1], ["6) Характеристика: изменения носят постепенный характер", 1], ["7) Характеристика: изменения зависят от условий среды / адекватны им (и в пределах нормы реакции)", 1], ["8) Прогноз: под согревающим компрессом вырастет белая шерсть", 1]], "max": 3, "ex": "Шкала оценивания из материалов: 7–8 ЭО — 3 балла; 4–6 ЭО — 2 балла; 3 ЭО — 1 балл. ВАЖНО: если вид изменчивости определён неверно — 0 баллов!"}, {"id": "tk_n1_seq", "type": "short", "sk": "methods", "ref": "02.19", "n": 1, "cross": ["1.2"], "lvl": 2, "q": "Рассмотрите таблицу «Методы биологических исследований» и запишите пропущенный термин (одно слово): «… — определение последовательности нуклеотидов в молекуле ДНК».", "a": ["секвенирование", "Секвенирование"], "ex": "В задании № 1 КИМ формулировка «определение последовательности нуклеотидов ДНК (или аминокислот белка)» требует точного термина «секвенирование»."}, {"id": "tk_n1_cyto", "type": "short", "sk": "methods", "ref": "02.22", "n": 1, "cross": ["1.2"], "lvl": 2, "q": "Запишите пропущенный термин (одно слово) для таблицы № 1 КИМ: «… метод — изучение кариотипа человека для выявления синдрома Дауна (трисомии по 21-й паре хромосом)».", "a": ["цитогенетический", "Цитогенетический", "цитологический", "Цитологический"], "ex": "Эталонный ответ ФИПИ — «цитогенетический» (реже как синоним засчитывают «цитологический»)."}, {"id": "tk_n1_twin", "type": "short", "sk": "methods", "ref": "02.13", "n": 1, "cross": ["1.2"], "lvl": 2, "q": "Запишите пропущенный термин (одно слово) для таблицы № 1 КИМ: «… метод — определение степени влияния условий внешней среды и генотипа на развитие признаков человека».", "a": ["близнецовый", "Близнецовый"], "ex": "Близнецовый метод сравнивает конкордантность монозиготных и дизиготных близнецов, разделяя вклад генотипа и среды."}, {"id": "tk_n7_comb", "type": "multi", "sk": "comb", "ref": "04.7", "n": 7, "lvl": 3, "q": "Выберите три верных ответа из шести. Какие процессы непосредственно приводят к возникновению комбинативной изменчивости?", "o": ["Кроссинговер в профазе I мейоза", "Независимое расхождение негомологичных хромосом в анафазе I мейоза", "Случайная встреча гамет при оплодотворении", "Ошибки ДНК-полимеразы при репликации ДНК", "Разрушение веретена деления под действием колхицина", "Увеличение площади листьев растения в тени"], "a": [0, 1, 2], "d": {"3": "Ошибки репликации создают генные мутации (мутационная изменчивость).", "4": "Колхицин вызывает полиплоидию (геномная мутация).", "5": "Изменение площади листьев в тени — модификационная изменчивость."}, "ex": "Только три события полового размножения перетасовывают существующие аллели: кроссинговер (профаза I), независимое расхождение хромосом (анафаза I) и случайное слияние гамет."}, {"id": "tk_n7_mut", "type": "multi", "sk": "mut", "ref": "05.13", "n": 7, "lvl": 3, "q": "Выберите три верных ответа из шести. Какие из перечисленных явлений относятся к хромосомным мутациям (перестройкам)?", "o": ["Утрата фрагмента короткого плеча 5-й хромосомы (синдром «кошачьего крика»)", "Поворот участка хромосомы на 180° (инверсия)", "Перенос участка хромосомы на негомологичную хромосому (транслокация)", "Выпадение одного нуклеотида тимина в цепи ДНК", "Трисомия по 21-й паре хромосом (синдром Дауна)", "Удвоение всего гаплоидного набора хромосом у пшеницы"], "a": [0, 1, 2], "d": {"3": "Выпадение одного нуклеотида — генная (точковая) мутация.", "4": "Трисомия-21 меняет число хромосом (47) — это геномная мутация.", "5": "Полиплоидия меняет число хромосом — это геномная мутация."}, "ex": "Хромосомные мутации меняют структуру (форму и состав участков) хромосом: делеция участка, дупликация, инверсия и транслокация."}, {"id": "tk_n20_table", "type": "match", "sk": "diseases", "ref": "06.16", "n": 20, "lvl": 3, "q": "Установите соответствие между кариотипом (или дефектом) и заболеванием человека (формат № 20 КИМ):", "left": ["47, XY, +21", "47, XXY", "45, X0", "47, XYY", "46, XX, 5p−"], "right": ["Синдром Дауна", "Синдром Клайнфельтера", "Синдром Шерешевского–Тёрнера", "Синдром Якобса", "Синдром «кошачьего крика»"], "a": [0, 1, 2, 3, 4], "ex": "Различай 47, XXY (Клайнфельтер) и 47, XYY (Якобс), а также 46, 5p− (хромосомная делеция, «кошачий крик»)."}, {"id": "tk_n6_xxy_origin", "type": "one", "sk": "diseases", "ref": "06.22", "n": 6, "lvl": 3, "q": "В результате какого конкретного сбоя мейоза может возникнуть синдром Якобса (47, XYY)?", "o": ["Только у отца при нерасхождении сестринских хроматид Y-хромосомы в анафазе II мейоза", "У матери при нерасхождении X-хромосом в анафазе I мейоза", "У отца при нерасхождении X и Y в анафазе I мейоза", "В результате хромосомной дупликации участка X-хромосомы"], "a": 0, "d": {"1": "У матери вообще нет Y-хромосомы.", "2": "Нерасхождение X и Y в анафазе I даёт сперматозоид XY → зиготу 47, XXY (синдром Клайнфельтера), а не XYY.", "3": "47, XYY — геномная мутация (лишняя целая Y-хромосома), а не дупликация участка X."}, "ex": "Для зиготы XYY нужен сперматозоид с двумя Y-хромосомами (22А + YY). Две копии одной Y-хромосомы расходятся именно как сестринские хроматиды в анафазе II сперматогенеза."}, {"id": "tk_n26_vavilov", "type": "part2", "sk": "comb", "ref": "04.15", "n": 26, "lvl": 3, "q": "У мягкой пшеницы обнаружена мутация, вызывающая устойчивость стебля к полеганию (короткостебельность). Опираясь на общебиологический закон, объясните, можно ли ожидать появления аналогичной мутации у ржи и ячменя, почему это возможно и какое практическое значение имеет данная закономерность для селекции и медицины.", "ideal": "1) Да, появление аналогичной мутации у ржи и ячменя можно ожидать на основании закона гомологических рядов в наследственной изменчивости, открытого Н. И. Вавиловым.\n2) Генетически близкие виды и роды (пшеница, рожь и ячмень относятся к семейству Злаки) произошли от общего предка и обладают сходным набором гомологичных генов.\n3) Сходные (гомологичные) гены могут мутировать сходным образом, давая параллельные ряды наследственной изменчивости.\n4) В селекции закон позволяет прогнозировать существование нужных признаков у родственных культур, целенаправленно искать их в природе или получать искусственным мутагенезом.\n5) В медицине закон позволяет подбирать животных-моделей с аналогичными наследственными заболеваниями (например, гемофилия у собак, альбинизм у грызунов) для их изучения.", "crit": [["1) Дан утвердительный ответ и назван закон гомологических рядов в наследственной изменчивости Н. И. Вавилова", 1], ["2) Указана причина: общее происхождение родственных видов (семейство Злаки) и наличие гомологичных генов", 1], ["3) Объяснено, что гомологичные гены мутируют сходным образом", 1], ["4) Значение для селекции: прогнозирование, целенаправленный поиск или получение мутагенезом нужных форм", 1], ["5) Значение для медицины: подбор животных-моделей наследственных болезней человека", 1]], "max": 3, "ex": "Три опоры для № 26 на закон Вавилова: закон + автор → общее происхождение и гомологичные гены → практическое прогнозирование."}, {"id": "tk_n26_consang", "type": "part2", "sk": "medgen", "ref": "07.5", "n": 26, "lvl": 3, "q": "Медико-генетическое консультирование предупреждает о повышенном риске рождения детей с тяжёлыми наследственными заболеваниями (например, фенилкетонурией) в близкородственных браках. Объясните генетическую причину этого риска. Почему своевременный неонатальный скрининг и диетотерапия позволяют ребёнку с фенилкетонурией вырасти умственно здоровым, и передастся ли мутантный аллель его будущим детям?", "ideal": "1) У каждого здорового человека в гетерозиготном состоянии (Aa) присутствуют скрытые редкие рецессивные мутантные аллели.\n2) Близкие родственники унаследовали одинаковые редкие рецессивные аллели от общих предков.\n3) В близкородственном браке резко повышается вероятность встречи двух одинаковых рецессивных аллелей и их перехода в гомозиготное состояние (aa), при котором болезнь проявляется в фенотипе (вероятность 25% при браке Aa × Aa).\n4) Диета без фенилаланина не изменяет генотип, но исключает из пищи токсичный субстрат, предотвращая накопление фенилпировиноградной кислоты и повреждение нервной системы (коррекция фенотипа).\n5) Мутантный аллель сохраняется в генотипе (в половых клетках) пациента и обязательно передастся его будущим детям (в 100% гамет гомозиготы aa).", "crit": [["1) У здоровых людей редкие рецессивные мутации скрыты в гетерозиготном состоянии (Aa)", 1], ["2) Родственники унаследовали одинаковые рецессивные аллели от общих предков → возрастает риск перехода в гомозиготу (aa)", 1], ["3) Диета не меняет генотип, но убирает фенилаланин и предотвращает накопление токсичного метаболита (коррекция фенотипа)", 1], ["4) Мутантный аллель сохраняется в половых клетках и передастся будущим детям", 1]], "max": 3, "ex": "Не пиши, что близкородственные браки «вызывают мутации» — они не повышают частоту мутагенеза, а переводят уже имеющиеся рецессивные мутации в гомозиготу."}, {"id": "tk_n26_colch_animal", "type": "part2", "sk": "mut", "ref": "05.18", "n": 26, "lvl": 3, "q": "В селекции растений широко применяют обработку проростков колхицином для получения высокоурожайных полиплоидных сортов. Объясните клеточный механизм действия колхицина. Почему полиплоидия широко распространена среди цветковых растений, но крайне редко встречается у раздельнополых животных?", "ideal": "1) Колхицин разрушает микротрубочки (нити) веретена деления (препятствует его формированию).\n2) После репликации ДНК в интерфазе хромосомы не могут разойтись к полюсам клетки в анафазе митоза, и в одной клетке остаётся кратно увеличенный набор хромосом (например, 4n — полиплоидия).\n3) У животных с хромосомным определением пола (XX/XY) полиплоидия нарушает баланс половых хромосом и аутосом, что ведёт к стерильности или гибели.\n4) У животных более сложный эмбриогенез (нарушение баланса генов часто летально) и отсутствует самоопыление/вегетативное размножение, позволяющее закрепить полиплоидную форму.\n5) У растений полиплоидия легко закрепляется за счёт самоопыления, вегетативного размножения и отсутствия у большинства видов жёсткой системы половых хромосом.", "crit": [["1) Колхицин разрушает микротрубочки / нарушает формирование веретена деления", 1], ["2) Хромосомы не расходятся в анафазе → кратное увеличение набора хромосом (полиплоидия)", 1], ["3) У животных нарушается хромосомное определение пола (баланс половых хромосом и аутосом)", 1], ["4) У животных сложный эмбриогенез (гибель зародышей) и нет самоопыления/вегетативного закрепления, в отличие от растений", 1]], "max": 3, "ex": "Классическая цепочка ФИПИ: колхицин → разрушение веретена деления → нерасхождение в анафазе → полиплоидия."}, {"id": "tk_n26_stem_ips", "type": "part2", "sk": "medgen", "ref": "07.12", "n": 26, "lvl": 3, "q": "В современной регенеративной медицине всё чаще используют собственные (аутологичные) стволовые клетки взрослого человека или индуцированные плюрипотентные стволовые клетки (iPS), полученные перепрограммированием клеток кожи пациента, вместо донорских эмбриональных стволовых клеток (ЭСК). Назовите два главных свойства стволовых клеток и укажите два преимущества аутологичных/iPS-клеток перед донорскими ЭСК.", "ideal": "1) Два свойства стволовых клеток: способность к многократному делению митозом (самообновлению) и способность к дифференцировке в специализированные клетки различных тканей.\n2) Преимущество 1 (иммунологическое): аутологичные и iPS-клетки генетически идентичны клеткам пациента, поэтому при их трансплантации не возникает иммунного отторжения (не требуется иммуносупрессия).\n3) Преимущество 2 (этическое): получение клеток взрослого организма и iPS-клеток не требует разрушения человеческих эмбрионов, что снимает серьёзные этические ограничения.", "crit": [["1) Названа способность к самообновлению (делению митозом)", 1], ["2) Названа способность к дифференцировке в специализированные клетки", 1], ["3) Иммунологическое преимущество: генетическая идентичность пациенту → отсутствие иммунного отторжения", 1], ["4) Этическое преимущество: не требуется разрушение эмбрионов", 1]], "max": 3, "ex": "Связка «свои клетки → одинаковые антигены/генотип → нет иммунного отторжения» регулярно проверяется в № 26 КИМ."}, {"id": "tk_n22_light", "type": "part2", "sk": "medgen", "ref": "07.16", "n": 22, "lvl": 3, "q": "Экспериментатор взял вегетативно размноженные побеги (клоны) одного растения и вырастил две группы по 40 растений при одинаковом поливе и почве, но при разной освещённости: группа А — яркий свет, группа Б — тень. Через 30 дней он измерил площадь листьев и построил вариационные кривые.\n\nСформулируйте нулевую гипотезу. Укажите независимую и зависимую переменные. Зачем для опыта взяли вегетативные клоны одного растения и одинаковую почву?", "ideal": "1) Нулевая гипотеза: площадь листьев растения не зависит от уровня освещённости.\n2) Независимая (задаваемая) переменная — уровень освещённости; зависимая (измеряемая) переменная — площадь листьев.\n3) Вегетативные клоны имеют одинаковый генотип (одинаковую норму реакции), а одинаковая почва исключает влияние различий в минеральном питании на рост листьев.\n4) При разных генотипах или разной почве зависимость между уровнем освещённости и площадью листьев не удастся установить в явном виде.", "crit": [["1) Нулевая гипотеза: площадь листьев не зависит от уровня освещённости", 1], ["2) Верно указаны независимая (освещённость) и зависимая (площадь листьев) переменные", 1], ["3) Клоны обеспечивают одинаковый генотип (норму реакции), а одинаковая почва — равное питание", 1], ["4) Иначе зависимость между освещённостью и площадью листьев не удастся установить в явном виде", 1]], "max": 3, "ex": "Обрати внимание на обязательную формулировку ФИПИ в пункте 4 — без неё часто теряют 1 балл."}], "subjectSlug": "biology", "_kim": {"1": {"b": 1, "l": "Б"}, "5": {"b": 1, "l": "Б"}, "6": {"b": 2, "l": "П"}, "7": {"b": 2, "l": "Б"}, "8": {"b": 2, "l": "П"}, "20": {"b": 2, "l": "П"}, "22": {"b": 3, "l": "П"}, "23": {"b": 3, "l": "В"}, "24": {"b": 3, "l": "В"}, "26": {"b": 4, "l": "В"}}, "_kon": {"01": {"t": "Модуль 01. Основные понятия и символика генетики", "x": "Генетика изучает два противоположных, но неразрывных свойства живого: **наследственность** (способность сохранять и передавать признаки потомству) и **изменчивость** (способность приобретать отличия). Чтобы не терять баллы на ЕГЭ, нужно строго различать масштабы: **ген → генотип (особь) → геном (гаплоидный набор вида) → кариотип (хромосомы соматической клетки вида) → генофонд (популяция)**."}, "01.7": {"t": "Модуль 01 · Точность определения гена", "x": "В кратких конспектах часто пишут: «ген — участок ДНК, кодирующий один белок». Для ЕГЭ на 100 баллов это слишком грубо: ген кодирует первичную структуру **одного полипептида** (белка) **или молекулу функциональной РНК** (тРНК, рРНК и др.), которая вообще не переводится в белок. А сложные белки (например, гемоглобин) собираются из нескольких полипептидных цепей, закодированных разными генами."}, "01.15": {"t": "Модуль 01 · 3. Пять терминов, которые чаще всего путают на ЕГЭ", "x": "• **[[генотип|Генотип]]** — Определение (канон ЕГЭ): Совокупность всех генов отдельной особи; Уровень: Отдельная особь (обычно 2n, бывает n); Ключевое отличие: Индивидуален у каждой особи (кроме клонов и однояйцевых близнецов); есть и у гаплоидных организмов (гаметофиты мхов, трутни, бактерии)\n• **[[фенотип|Фенотип]]** — Определение (канон ЕГЭ): Совокупность всех внешних и внутренних признаков организма; Уровень: Особь; Ключевое отличие: Формируется на основе генотипа под влиянием среды\n• **[[геном|Геном]]** — Определение (канон ЕГЭ): Совокупность всех генов гаплоидного набора хромосом вида; Уровень: Вид (гаплоидный, n); Ключевое отличие: Характеризует **гены** одного набора (n = 23 у человека)…"}, "01.19": {"t": "Модуль 01 · Граница правила: полное, неполное доминирование и кодоминирование", "x": "Никогда не пиши в части 2, что доминантный признак «проявляется всегда»! Это верно **только при полном доминировании**. При **неполном доминировании** (у ночной красавицы: AA — красные цветки, aa — белые) у гетерозиготы Aa проявляется **промежуточный** признак — розовые цветки. А при **кодоминировании** (например, IV группа крови I^{A}I^{B}) оба доминантных аллеля проявляются одновременно и независимо."}, "02": {"t": "Модуль 02. Методы генетики и изучения генетики человека", "x": "Каждый метод генетики отвечает на **свой** вопрос. **Гибридологический** и **генеалогический** устанавливают характер наследования, **близнецовый** разделяет вклад генотипа и среды, **цитогенетический** видит хромосомы под микроскопом (геномные и хромосомные мутации), **биохимический** ищет сломанные ферменты в крови и моче, **молекулярно-генетический** читает саму последовательность ДНК, а **популяционно-статистический** считает частоты аллелей в популяции."}, "02.7": {"t": "Модуль 02 · 2. Полная карта методов генетики для ЕГЭ", "x": "• **[[гибридологический метод|Гибридологический]]** — В чём суть: Скрещивание организмов с контрастными признаками и количественный анализ потомства; Что выявляет / зачем нужен: Характер наследования признака, генотипы родителей (неприменим к человеку); Ключевые слова в № 1 и № 20 КИМ: «скрещивание», «анализ потомства», «гибриды F1/F2», «Мендель»\n• **[[генеалогический метод|Генеалогический]]** — В чём суть: Составление и анализ родословных в ряде поколений; Что выявляет / зачем нужен: Тип наследования (доминантный/рецессивный, аутосомный/сцепленный с полом), прогноз риска для детей; Ключевые слова в № 1 и № 20 КИМ: «родословная», «ряд поколений», «наследование в семье»…"}, "02.8": {"t": "Модуль 02 · Ловушка ЕГЭ: что видит микроскоп, а что нет", "x": "Самая частая ловушка № 1 и № 20 КИМ: **цитогенетический метод НЕ видит генные (точковые) мутации!** В световой микроскоп видна целая хромосома (её число, длина, крупная делеция или транслокация), но невозможно разглядеть замену одного нуклеотида. Поэтому синдром Дауна и синдром Клайнфельтера выявляют **цитогенетически**, а фенилкетонурию, гемофилию или альбинизм — **биохимическим** или **молекулярно-генетическим** методом."}, "02.13": {"t": "Модуль 02 · 3. Генеалогический и близнецовый методы в деталях", "x": "Как работает логика близнецового метода? В учебниках ФПУ и на ЕГЭ встречаются **два равноправных варианта** объяснения:"}, "02.17": {"t": "Модуль 02 · 4. Этапы кариотипирования (для № 8) и работа биохимического/молекулярного анализа", "x": "Для задания № 8 запомни порядок этапов **цитогенетического метода (кариотипирования)**: 1) взятие и культивирование клеток (обычно лейкоцитов крови) со стимуляцией митоза → 2) обработка **колхицином** для остановки деления на стадии **метафазы** (когда хромосомы максимально спирализованы и лучше всего видны) → 3) фиксация, окрашивание и микрофотографирование хромосом → 4) раскладка хромосом попарно по размеру и форме (кариограмма)."}, "02.19": {"t": "Модуль 02 · 4. Этапы кариотипирования (для № 8) и работа биохимического/молекулярного анализа", "x": "А если нужно увидеть саму «опечатку» в тексте ДНК (например, у здорового носителя гена, у которого фермент ещё работает за счёт второго нормального аллеля), применяют **молекулярно-генетический метод** — [[секвенирование]] (прочтение последовательности нуклеотидов ДНК)."}, "02.22": {"t": "Модуль 02 · 4. Этапы кариотипирования (для № 8) и работа биохимического/молекулярного анализа", "x": "**Шаг 1.** **Разбор 5 ситуаций из реального № 1 и № 20 КИМ.** Какой метод вписать в таблицу?\n**Шаг 2.** **Ситуация 1:** «Выявление трисомии по 21-й паре хромосом (синдрома Дауна)» → речь о числе хромосом в кариотипе → **цитогенетический** (основной эталонный термин ФИПИ; реже принимают синоним *цитологический*).\n**Шаг 3.** **Ситуация 2:** «Определение степени влияния факторов внешней среды на развитие интеллекта и роста» → разделение вклада генотипа и среды → **близнецовый**.\n**Шаг 4.** **Ситуация 3:** «Выявление повышенного содержания фенилаланина в крови новорождённого» → химический анализ метаболита → **биохимический**.\n**Шаг 5.** **Ситуация 4:** «Определение типа наследования гемофилии в нескольких поколениях одной семьи» → анализ семейной родословной → **генеалогический**.…"}, "03": {"t": "Модуль 03. Виды изменчивости, модификации, норма реакции и вариационная кривая", "x": "**Модификационная (ненаследственная) изменчивость** меняет только **фенотип** под влиянием среды, не затрагивая ДНК. При этом по наследству передаётся не сам изменённый признак (загар или крупный лист), а **норма реакции** — генетически заданный коридор, внутри которого признак способен меняться."}, "03.4": {"t": "Модуль 03 · Сравнение ненаследственной и наследственной изменчивости", "x": "• **Что меняется** — Ненаследственная (модификационная): Только **фенотип** (генотип не затронут); Наследственная (генотипическая): **Генотип** (ДНК, хромосомы или сочетания аллелей); Почему важно: От этого зависит передача потомству\n• **Передача по наследству** — Ненаследственная (модификационная): **Не передаётся** потомству; Наследственная (генотипическая): **Передаётся** потомству (если затронуты половые клетки / вегетативный побег); Почему важно: Главный критерий разделения\n• **Характер проявления** — Ненаследственная (модификационная): **Групповой (массовый)**, **определённый** (сходно у всех особей в одних условиях); Наследственная (генотипическая): **Индивидуальный**, **неопределённый** (у каждой особи возникает случайно); Почему важно: Среда действует сразу на всю группу…"}, "03.6": {"t": "Модуль 03 · 2. Норма реакции: узкая и широкая", "x": "Представь, что генотип выдал организму не одно жёсткое число, а «бегунок» с минимальной и максимальной отметкой. Этот генетически заданный диапазон возможных значений признака называется [[норма реакции|нормой реакции]]."}, "03.8": {"t": "Модуль 03 · 2. Норма реакции: узкая и широкая", "x": "• **Узкая норма реакции** — Признак почти не зависит от условий среды. Если он сильно изменится, организм погибнет или не сможет размножаться.\n• **Широкая норма реакции** — Признак сильно колеблется в зависимости от питания, освещения, температуры, влажности и физической нагрузки."}, "03.9": {"t": "Модуль 03 · Классические ловушки ЕГЭ на модификации", "x": "Осторожно с ловушками ЕГЭ по норме реакции и модификациям!\n• **Удойность vs жирность молока:** количество молока (удойность) имеет **широкую** норму реакции (сильно зависит от корма), а **жирность молока** — **узкую** (жёстко контролируется генотипом породы).\n• **«Ложная окраска»:** хотя окраска обычно имеет узкую норму реакции, на ЕГЭ обожают **три эталонных примера модификационной изменчивости**:\n1) **Гималайский кролик:** фермент тирозиназа (синтез чёрного меланина) работает только при пониженной температуре → уши, лапы, нос и хвост чёрные, а тёплая спина белая. Если выбрить спину и приложить лёд — отрастёт чёрная шерсть!\n2) **Китайская примула:** при 15–20 °C цветки красные, при 30–35 °C — белые.\n3) **Стрелолист:** на одном растении подводные листья лентовидные, плавающие — округлые, воздушные — стреловидные (разная среда вокруг листа)."}, "03.10": {"t": "Модуль 03 · Эталонные примеры модификационной изменчивости на ЕГЭ: стрелолист и гималайский кролик", "x": "У одного растения стрелолиста форма листьев зависит от среды (воздух / поверхность воды / толща воды), а у гималайского кролика тёмный пигмент синтезируется на охлаждаемых участках тела.\n• 1. **Воздушные стреловидные листья** — Развиваются над водой на воздухе\n• 2. **Плавающие округлые листья** — Развиваются на границе воды и воздуха\n• 3. **Подводные лентовидные листья** — Развиваются в толще воды\n• 4. **Тёмные уши гималайского кролика** — Пониженная температура → активна тирозиназа → синтез меланина\n• 5. **Тёмный нос (и лапы/хвост)** — На тёплой спине фермент неактивен → шерсть остаётся белой"}, "03.11": {"t": "Модуль 03 · Всегда ли модификации обратимы?", "x": "Модификации часто обратимы (зимой загар сходит, при скудном корме падают удои, а при хорошем — возвращаются). Но **не всякая модификация обратима**! Если ребёнок перенёс рахит из-за нехватки витамина D, искривление костей останется на всю жизнь — однако это всё равно модификация, потому что ДНК не изменилась и детям искривление не передастся."}, "03.14": {"t": "Модуль 03 · 3. Вариационный ряд и вариационная кривая (В. Иогансен)", "x": "1. Собрать выборку однородных объектов (например, 100 листьев с одного дерева) и измерить у каждого длину.\n2. Выстроить значения признака от минимума к максимуму — получится [[вариационный ряд]]. Каждое отдельное значение в нём называется **вариантой (v)**.\n3. Посчитать, сколько раз встретилось каждое значение (**частота встречаемости, p**), и построить график — [[вариационная кривая|вариационную кривую]]."}, "03.16": {"t": "Модуль 03 · Вариационный ряд длины листьев", "x": "Листья одного растения, выстроенные от минимального к максимальному значению признака, наглядно образуют вариационный ряд в пределах нормы реакции.\n• 1. **Минимальная варианта** — Нижняя граница нормы реакции\n• 2. **Средние значения** — Встречаются в природе чаще всего\n• 3. **Максимальная варианта** — Верхняя граница нормы реакции"}, "03.20": {"t": "Модуль 03 · Мост к КИМ (№ 5, № 6, № 7, № 22–24 КИМ)", "x": "**Как спрашивают:** Распознать модификационную изменчивость по примерам, прочитать вариационную кривую или объяснить, почему у клонов в разных условиях получились разные средние значения.\n**На чём ловят:** Грубая ошибка, за которую снимают баллы в части 2: написать «под действием среды изменилась норма реакции» или «у растений в тени мутировали гены». Правильно: **норма реакции обусловлена генотипом и осталась прежней; изменилась лишь степень проявления признака (фенотип) в её пределах**.\n**Как читать:** Если в условии дана **чистая линия**, **клон** или **однояйцевые близнецы** — их генотипы равны, значит, любое различие между группами в разных условиях вызвано средой (модификацией)."}, "04": {"t": "Модуль 04. Комбинативная изменчивость и закон гомологических рядов Н. И. Вавилова", "x": "**Комбинативная изменчивость** не создаёт новых генов — она перетасовывает уже существующие аллели в новые сочетания за счёт трёх механизмов: **кроссинговера в профазе I мейоза**, **независимого расхождения хромосом в анафазе I мейоза** и **случайного слияния гамет**. А **закон гомологических рядов Н. И. Вавилова** объясняет, почему у родственных видов возникают параллельные ряды сходных наследственных изменений."}, "04.4": {"t": "Модуль 04 · 1. Как работает комбинативная изменчивость", "x": "Вспомним из цитологии (опора для № 8): в **мейозе I** идут *профаза I* (сближение гомологичных хромосом — конъюгация — и **кроссинговер**), *метафаза I* (выстраивание бивалентов по экватору), *анафаза I* (независимое расхождение **двухроматидных** гомологичных хромосом к полюсам) и *телофаза I*; затем в **мейозе II** к полюсам в *анафазе II* расходятся сестринские хроматиды, а гаплоидные гаметы (n) сливаются при оплодотворении. Именно на трёх этапах этого пути «тасуется колода»:"}, "04.6": {"t": "Модуль 04 · 1. Как работает комбинативная изменчивость", "x": "1. **Кроссинговер в профазе I мейоза** — обмен гомологичными участками между несестринскими хроматидами сблизившихся (конъюгировавших) гомологичных хромосом. Создаёт новые комбинации аллелей прямо внутри одной хромосомы.\n2. **Независимое расхождение негомологичных хромосом в анафазе I мейоза** (а после кроссинговера — и хроматид в анафазе II) — к каждому полюсу клетки случайным образом уходит то отцовская, то материнская хромосома из каждой пары. У человека с 23 парами только этот механизм даёт $2^{23} > 8$ миллионов вариантов гамет!\n3. **Случайное слияние гамет при оплодотворении** — любая из миллионов яйцеклеток случайно встречается с любым из миллионов сперматозоидов."}, "04.7": {"t": "Модуль 04 · Ловушки ЕГЭ по комбинативной изменчивости", "x": "Три частых капкана ЕГЭ по комбинативной изменчивости:\n1) **Конъюгация vs кроссинговер:** сама по себе конъюгация — это только сближение гомологичных хромосом; новые комбинации генов создаёт именно **кроссинговер** (обмен участками), хотя в заданиях части 1 их часто пишут вместе: «конъюгация и кроссинговер».\n2) **Почему комбинации называют «нестабильными»?** Потому что удачное сочетание аллелей, возникшее у гибрида, при следующем половом размножении снова распадётся и перетасуется в мейозе (у растений его закрепляют вегетативным размножением).\n3) **При бесполом (вегетативном) размножении** комбинативной изменчивости нет — нет ни мейоза, ни оплодотворения."}, "04.12": {"t": "Модуль 04 · Каноническая формулировка закона Н. И. Вавилова.", "x": "**Закон гомологических рядов в наследственной изменчивости (Н. И. Вавилов):** виды и роды, генетически близкие, характеризуются сходными рядами наследственной изменчивости с такой правильностью, что, зная ряд форм в пределах одного вида, можно предвидеть нахождение параллельных форм у других видов и родов. Чем ближе виды в системе (чем теснее родство), тем полнее сходство рядов."}, "04.15": {"t": "Модуль 04 · 3. Закон гомологических рядов в наследственной изменчивости (Н. И. Вавилов)", "x": "**Шаг 1.** **Разбор вслух (задание № 26 КИМ).** У мягкой пшеницы обнаружена мутация, вызывающая устойчивость стебля к полеганию (карликовость). Опираясь на закон Н. И. Вавилова, объясните, можно ли ожидать появления такой же мутации у ржи и ячменя, почему это возможно и какое значение имеет для селекции.\n**Шаг 1. Прямой ответ и ссылка на закон.** Да, появление аналогичной мутации у ржи и ячменя можно ожидать на основании **закона гомологических рядов в наследственной изменчивости Н. И. Вавилова**: генетически близкие виды и роды имеют сходные ряды наследственной изменчивости.\n**Шаг 2. Причина (эволюционно-генетическая).** Пшеница, рожь и ячмень относятся к одному семейству Злаки, произошли от общего предка и обладают сходным набором **гомологичных генов**, которые могут мутировать сходным образом.…"}, "05": {"t": "Модуль 05. Мутационная изменчивость, классификация мутаций и мутагены", "x": "**Мутации** — это внезапные, скачкообразные, случайные изменения самого наследственного материала (ДНК или хромосом). Главная классификация для ЕГЭ делит их по уровню изменения генотипа на **генные** (внутри одного гена), **хромосомные** (перестройки участков хромосом) и **геномные** (изменение числа хромосом: **полиплоидия** и **анеуплоидия**)."}, "05.8": {"t": "Модуль 05 · 2. Главная классификация: генные, хромосомные и геномные мутации", "x": "Именно эту тройку чаще всего проверяют в заданиях № 5, 6, 7, 20 и 24–26. Запоминай их по масштабу поломки: **буква → страница → количество томов**."}, "05.13": {"t": "Модуль 05 · Б. Хромосомные мутации (перестройки) — затрагивают сразу много генов", "x": "Меняют структуру (форму и состав участков) одной или нескольких хромосом. Их четыре основных вида:"}, "05.18": {"t": "Модуль 05 · Полиплоидия vs Анеуплоидия (гетероплоидия)", "x": "• **Полиплоидия (кратное увеличение n)**: Число хромосом увеличивается в целое число раз: 3n (триплоид), 4n (тетраплоид), 6n (гексаплоид).; Причина: после репликации ДНК в S-периоде интерфазы (2n4c) происходит **разрушение (или нарушение формирования) нитей веретена деления** (например, алкалоидом **колхицином**) → в анафазе хромосомы не расходятся к полюсам, митоз прерывается, и клетка получает удвоенный набор (4n).; У **растений** часто полезна (крупные плоды, высокая урожайность: пшеница 6n, картофель 4n; легко закрепляется самоопылением и вегетативно). У **животных** почти всегда летальна из-за нарушения хромосомного определения пола (XX/XY), сбоев сложного эмбриогенеза и отсутствия самоопыления.…"}, "05.19": {"t": "Модуль 05 · Ловушка ЕГЭ: анеуплоидия бывает и с плюсом, и с минусом", "x": "Запомни исправление популярной ошибки: **анеуплоидия — это НЕ только увеличение числа хромосом!** Это любое **некратное гаплоидному набору изменение**: и добавление (2n+1 — трисомия), и утрата (2n−1 — моносомия, 2n−2 — нуллисомия). Синдром Шерешевского–Тёрнера (45, X0) — классическая анеуплоидия с уменьшением числа хромосом."}, "05.20": {"t": "Модуль 05 · Эффект полиплоидии у растений: диплоид (2n) vs тетраплоид (4n)", "x": "Кратное увеличение хромосомного набора у растений приводит к увеличению размеров клеток, листьев, цветков и плодов, что широко используют в селекции.\n• 1. **Диплоидное растение (2n)** — Исходный размер листьев, цветков и плодов\n• 2. **Тетраплоидное растение (4n)** — Кратное увеличение набора хромосом → более крупные листья, цветки и плоды"}, "05.22": {"t": "Модуль 05 · 3. Остальные классификации мутаций", "x": "• ****По типу клеток**** — Виды мутаций: **Соматические** (в клетках тела) и **генеративные / половые** (в гаметах); Что важно знать для ЕГЭ: Соматические **не передаются** при половом размножении, но их **можно сохранить при вегетативном (бесполом)** размножении (например, черенком ветки с крупными яблоками). Половые передаются потомству при половом размножении.\n• ****По локализации**** — Виды мутаций: **Ядерные** (в ДНК ядра) и **цитоплазматические** (в ДНК митохондрий и хлоропластов); Что важно знать для ЕГЭ: Цитоплазматические мутации у животных и большинства растений наследуются **по материнской линии**, так как яйцеклетка несёт цитоплазму с органоидами, а сперматозоид — почти только ядро (пример: пестролистность у растений).…"}, "06": {"t": "Модуль 06. Кариотип человека и наследственные заболевания", "x": "Нормальный **кариотип человека** — **46 хромосом** (2n = 46: 44 аутосомы + XX у женщин или XY у мужчин). Все наследственные болезни делят на три группы: **генные** (поломка одного гена → часто дефект фермента), **хромосомные** (вызваны хромосомными перестройками **или геномными** мутациями — нерасхождением хромосом в мейозе) и **полигенные** (наследуется лишь предрасположенность)."}, "06.5": {"t": "Модуль 06 · 1. Кариотип человека в норме", "x": "Формула нормального кариотипа записывается так: **46, XX** (женский) и **46, XY** (мужской). В нормальной зрелой гамете человека ровно **23 хромосомы** (n = 23)."}, "06.10": {"t": "Модуль 06 · 3. Генные (моногенные) болезни для ЕГЭ", "x": "• ****Фенилкетонурия (ФКУ)**** — Тип наследования: Аутосомно-рецессивный; Биохимический механизм и проявления: Нет фермента, превращающего аминокислоту **фенилаланин** в тирозин. Фенилаланин превращается в токсичную фенилпировиноградную кислоту → поражение нервной системы и умственная отсталость. Предотвращается ранней **диетой** без фенилаланина!\n• ****Галактоземия**** — Тип наследования: Аутосомно-рецессивный; Биохимический механизм и проявления: Нет фермента расщепления моносахарида **галактозы** (поступающей из молочного сахара). Накопление галактозы поражает печень, глаза (катаракта) и мозг. Корректируется исключением молока.\n• ****Альбинизм**** — Тип наследования: Аутосомно-рецессивный; Биохимический механизм и проявления: Нарушение синтеза фермента тирозиназы → отсутствие пигмента **меланина** в коже, волосах и радужке глаза (у растений «альбинизмом» называют отсутствие хлорофилла — это другой ген).…"}, "06.11": {"t": "Модуль 06 · Точность по галактоземии, гипотиреозу и тератогенам", "x": "Исправляем две частые ошибки из школьных конспектов и добавляем важное разграничение ЕГЭ:\n1) **Галактоземия** — это нарушение обмена **галактозы**, а **не лактозы**! Нарушение расщепления самой лактозы называется *лактазной недостаточностью* и не вызывает тяжёлого поражения мозга.\n2) **Гипотиреоз** (снижение функции щитовидной железы) — в большинстве случаев **приобретённый** синдром (нехватка йода, аутоиммунный тиреоидит), а не наследственная болезнь; аутосомно-рецессивно наследуются лишь редкие врождённые формы.\n3) **Врождённое ≠ наследственное!** Врождённые пороки развития могут быть **ненаследственными** — вызваны действием **тератогенов** на зародыш во время беременности (алкоголь, никотин, вирус краснухи, токсичные лекарства). И наоборот: многие **наследственные** болезни проявляются не при рождении, а позже (в детстве или взрослом возрасте)."}, "06.12": {"t": "Модуль 06 · Серповидноклеточная анемия (генная мутация)", "x": "Замена одной аминокислоты в β-цепи гемоглобина деформирует эритроциты: вместо двояковогнутых дисков они принимают форму серпа.\n• 1. **Серповидный эритроцит** — Деформирован из-за мутантного гемоглобина HbS\n• 2. **Нормальный эритроцит** — Двояковогнутый диск с нормальным гемоглобином HbA"}, "06.16": {"t": "Модуль 06 · 4. Хромосомные и геномные болезни человека", "x": "• ****Синдром Дауна**** — Кариотип: 47, +21 (трисомия по 21-й аутосоме); Точный тип мутации для ЕГЭ: **Геномная** (анеуплоидия, трисомия); Основные проявления: Характерные черты лица, задержка умственного и физического развития, частые пороки сердца\n• ****Синдром Патау**** — Кариотип: 47, +13 (трисомия по 13-й аутосоме); Точный тип мутации для ЕГЭ: **Геномная** (анеуплоидия, трисомия); Основные проявления: Тяжёлые пороки развития мозга, сердца, микроцефалия, расщелина губы/нёба\n• ****Синдром Эдвардса**** — Кариотип: 47, +18 (трисомия по 18-й аутосоме); Точный тип мутации для ЕГЭ: **Геномная** (анеуплоидия, трисомия); Основные проявления: Короткая шея, тяжёлые врождённые пороки сердца и других органов, задержка развития…"}, "06.17": {"t": "Модуль 06 · Критическое исправление: Клайнфельтер (XXY) vs Якобс (XYY)", "x": "Исправляем грубую ошибку, которая кочует по шпаргалкам: **кариотип 47, XYY (и XYYY) — это НЕ синдром Клайнфельтера!** Синдром Клайнфельтера — это лишняя **X**-хромосома при наличии Y (47, XXY, реже XXXY, XXXXY). А лишняя **Y**-хромосома (47, XYY) — это отдельный **синдром Якобса**."}, "06.18": {"t": "Модуль 06 · Кариограмма человека с синдромом Дауна (47, XY, +21)", "x": "В 21-й паре аутосом видны три хромосомы вместо двух (выделены красной рамкой) — результат цитогенетического анализа (кариотипирования).\n• 1. **Трисомия по 21-й паре** — Три хромосомы вместо двух — геномная мутация (синдром Дауна)\n• 2. **Половые хромосомы XY** — Мужской кариотип 47, XY, +21"}, "06.20": {"t": "Модуль 06 · 5. Как возникает трисомия и моносомия: механизм в мейозе", "x": "Почему у здоровых родителей с нормальным кариотипом 46 рождается ребёнок с 47 или 45 хромосомами? Причина — **нарушение расхождения хромосом при гаметогенезе (в мейозе)** у одного из родителей: либо гомологичные хромосомы не разошлись в **анафазе I мейоза**, либо сестринские хроматиды не разошлись в **анафазе II мейоза**. С возрастом матери риск трисомии-21 заметно растёт: у женщин первичные ооциты закладываются ещё в эмбриогенезе и десятилетиями «ждут» в профазе I мейоза, накапливая поломки белков, удерживающих хромосомы, и веретена деления."}, "06.21": {"t": "Модуль 06 · 5. Как возникает трисомия и моносомия: механизм в мейозе", "x": "Если в мейозе не разошлась пара хромосом (21-я или половые), после завершения мейоза II образуются аномальные гаметы (n+1 = 24 и n−1 = 22). Их слияние с нормальной гаметой (n = 23) даёт трисомию (47) или моносомию (45)."}, "06.22": {"t": "Модуль 06 · 5. Как возникает трисомия и моносомия: механизм в мейозе", "x": "**Шаг 1.** **Разбор вслух (задание № 24 / № 26 КИМ).** У здоровых родителей родился ребёнок с геномной мутацией (трисомия-21 47, +21, синдром Клайнфельтера 47, XXY или моносомия 45, X0). Назовите тип мутации, метод диагностики и пути образования таких зигот.\n**Шаг 1. Тип мутации и метод.** Все три случая — **геномные** мутации (**анеуплоидии**). Диагностируются **цитогенетическим** методом (кариотипированием).\n**Шаг 2. Трисомия-21 (47, +21, синдром Дауна) и моносомия (45, X0, синдром Шерешевского–Тёрнера).** При нерасхождении 21-й пары в анафазе I или хроматид в анафазе II образуется гамета n+1 = 24 (две 21-е хромосомы); сливаясь с нормальной гаметой n = 23, она даёт зиготу 47, +21. А если не разошлись половые хромосомы, образуется гамета n−1 = 22 (22А + 0, без половой хромосомы); сливаясь с нормальной гаметой 22А + X (23), она даёт зиготу 45, X0.…"}, "07": {"t": "Модуль 07. Медицинская генетика, стволовые клетки и стратегия заданий 22–26", "x": "**Медицинская генетика** снижает риск и тяжесть наследственных болезней на трёх рубежах: **профилактика** (медико-генетическое консультирование, защита от мутагенов, исключение близкородственных браков), **ранняя диагностика** (пренатальная и неонатальный скрининг) и **коррекция фенотипа** (диета, ферменты, гормоны). А **стволовые клетки** — недифференцированные клетки, способные к самообновлению и превращению в специализированные ткани — открывают путь к регенеративной медицине."}, "07.4": {"t": "Модуль 07 · 1. Значение медицинской генетики: три линии защиты", "x": "• ****1. Профилактика**** — Инструменты медицинской генетики: Медико-генетическое консультирование (анализ родословных, ДНК-тест на носительство), отказ от близкородственных браков, защита от мутагенов (радиация, алкоголь, курение, тератогены); Биологический смысл и примеры для ЕГЭ: Позволяет рассчитать вероятность рождения больного ребёнка ещё до беременности и снизить частоту новых мутаций в половых клетках.\n• ****2. Ранняя диагностика**** — Инструменты медицинской генетики: **Пренатальная** (до рождения): УЗИ, **амниоцентез** (анализ околоплодных вод), **биопсия хориона** → кариотипирование. **Неонатальный скрининг** (анализ крови из пятки новорождённого в роддоме); Биологический смысл и примеры для ЕГЭ: Выявляет синдромы Дауна/Эдвардса до родов, а фенилкетонурию и галактоземию — в первые дни жизни, пока мозг ещё не повреждён.…"}, "07.5": {"t": "Модуль 07 · Почему опасны близкородственные браки?", "x": "Почему в заданиях № 26 часто спрашивают о **вреде близкородственных браков**? У каждого здорового человека в гетерозиготном состоянии (Aa) скрыто несколько редких рецессивных мутаций. У неродственных людей эти мутации обычно находятся в *разных* генах, поэтому дети здоровы. А близкие родственники унаследовали одинаковые редкие рецессивные аллели от общих предков: если оба супруга оказались носителями (Aa × Aa), то вероятность рождения больного ребёнка (aa) сразу взлетает до **25%** (1/4) — рецессивные аллели переходят в гомозиготное состояние и проявляются в фенотипе."}, "07.10": {"t": "Модуль 07 · 2. Стволовые клетки: от зиготы к специализированным тканям", "x": "По мере развития организма потентность стволовых клеток сужается: от зиготы, способной дать целый организм и плаценту, до стволовых клеток конкретных тканей взрослого."}, "07.11": {"t": "Модуль 07 · 2. Стволовые клетки: от зиготы к специализированным тканям", "x": "**Зачем стволовые клетки медицине?** В **регенеративной медицине** их применяют для восстановления повреждённых тканей и органов (классический пример — **пересадка красного костного мозга** при лейкозах и лучевой болезни), для выращивания клеточных культур, на которых безопасно испытывают новые лекарства, и для изучения механизмов развития организма и рака."}, "07.12": {"t": "Модуль 07 · ЭСК vs собственные стволовые и iPS-клетки (на 100 баллов)", "x": "Почему в заданиях № 26 часто спрашивают о преимуществах **собственных (аутологичных) стволовых клеток взрослого** и **индуцированных плюрипотентных (iPS-клеток)** перед эмбриональными (ЭСК)? Потому что собственные клетки **не вызывают иммунного отторжения** (генетически идентичны пациенту) и их получение **не требует разрушения эмбриона** (нет этической проблемы)."}, "07.15": {"t": "Модуль 07 · 3. Эвристика части 2 ЕГЭ: как решать № 22–23 (эксперимент по изменчивости)", "x": "• **Независимая переменная (задаваемая экспериментатором)** — фактор, который учёный специально меняет между группами (например, освещённость, температура, концентрация удобрения).\n• **Зависимая переменная (измеряемая)** — признак, который меняется в ответ и который измеряют (например, длина листа, масса клубней, интенсивность окраски).\n• **Нулевая гипотеза** — предположение о том, что **нет зависимости** между независимой и зависимой переменными (например: «Площадь листьев растения не зависит от уровня освещённости»).\n• **Отрицательный контроль** — экспериментальный контроль (опыт), при котором изучаемый объект **не подвергается экспериментальному воздействию** при сохранении всех остальных условий (например, группа без удобрения; если фактор нельзя «обнулить» — как свет или температуру — используют естественное/стандартное условие либо указывают, что классический отрицательный контроль поставить невозможно).…"}, "07.16": {"t": "Модуль 07 · 3. Эвристика части 2 ЕГЭ: как решать № 22–23 (эксперимент по изменчивости)", "x": "**Шаг 1.** **Полный разбор мини-модуля № 22–23 КИМ.** Экспериментатор взял вегетативно размноженные побеги (клоны) одного растения и вырастил две группы по 40 растений при одинаковом поливе и почве, но при разной освещённости: группа А — яркий свет, группа Б — тень. Через 30 дней он измерил площадь листьев в обеих группах и построил вариационные кривые.\n**Шаг 2.** **Вопрос 1 (№ 22): сформулируйте нулевую гипотезу, назовите независимую и зависимую переменные.**\n• *Нулевая гипотеза:* площадь листьев растения не зависит от уровня освещённости.\n• *Независимая переменная:* уровень освещённости.\n• *Зависимая переменная:* площадь листьев.\n**Шаг 3.** **Вопрос 2 (№ 22): почему для опыта взяли вегетативные клоны одного растения, одинаковую почву/полив и по 40 растений в группе?**…"}}, "_kt": "Основы и методы генетики, изменчивость и наследственные заболевания человека", "_mods": {"01": "Основные понятия и символика генетики", "02": "Методы генетики и изучения генетики человека", "03": "Виды изменчивости, модификации, норма реакции и вариационная кривая", "04": "Комбинативная изменчивость и закон гомологических рядов Н. И. Вавилова", "05": "Мутационная изменчивость, классификация мутаций и мутагены", "06": "Кариотип человека и наследственные заболевания", "07": "Медицинская генетика, стволовые клетки и стратегия заданий 22–26"}, "_skm": {"terms": ["01"], "methods": ["02"], "modif": ["03"], "comb": ["04"], "mut": ["05"], "diseases": ["06"], "medgen": ["07"]}, "_fig": [{"sk": "modif", "ref": "03.10", "n": 5, "nm": 6, "gen": true, "id": "modifikacii-primery", "file": "topics/biology/osnovy-genetiki-izmenchivost/figures/modifikacii-primery.png", "marks": [["1", "Воздушные стреловидные листья", "Развиваются над водой на воздухе"], ["2", "Плавающие округлые листья", "Развиваются на границе воды и воздуха"], ["3", "Подводные лентовидные листья", "Развиваются в толще воды"], ["4", "Тёмные уши гималайского кролика", "Пониженная температура → активна тирозиназа → синтез меланина"], ["5", "Тёмный нос (и лапы/хвост)", "На тёплой спине фермент неактивен → шерсть остаётся белой"]], "pts": {"1": [0.34, 0.21], "2": [0.15, 0.49], "3": [0.16, 0.68], "4": [0.82, 0.23], "5": [0.91, 0.41]}, "t": "Эталонные примеры модификационной изменчивости на ЕГЭ: стрелолист и гималайский кролик"}, {"sk": "modif", "ref": "03.16", "n": 5, "nm": 6, "gen": true, "id": "variacionnyj-ryad-listev", "file": "topics/biology/osnovy-genetiki-izmenchivost/figures/variacionnyj-ryad-listev.png", "marks": [["1", "Минимальная варианта", "Нижняя граница нормы реакции"], ["2", "Средние значения", "Встречаются в природе чаще всего"], ["3", "Максимальная варианта", "Верхняя граница нормы реакции"]], "pts": {"1": [0.06, 0.62], "2": [0.5, 0.5], "3": [0.92, 0.45]}, "t": "Вариационный ряд длины листьев"}, {"sk": "mut", "ref": "05.20", "n": 5, "gen": true, "id": "poliploidiya-rasteniya", "file": "topics/biology/osnovy-genetiki-izmenchivost/figures/poliploidiya-rasteniya.png", "marks": [["1", "Диплоидное растение (2n)", "Исходный размер листьев, цветков и плодов"], ["2", "Тетраплоидное растение (4n)", "Кратное увеличение набора хромосом → более крупные листья, цветки и плоды"]], "pts": {"1": [0.24, 0.54], "2": [0.69, 0.48]}, "t": "Эффект полиплоидии у растений: диплоид (2n) vs тетраплоид (4n)"}, {"sk": "diseases", "ref": "06.12", "n": 5, "gen": true, "id": "serpovidnye-eritrocity", "file": "topics/biology/osnovy-genetiki-izmenchivost/figures/serpovidnye-eritrocity.png", "marks": [["1", "Серповидный эритроцит", "Деформирован из-за мутантного гемоглобина HbS"], ["2", "Нормальный эритроцит", "Двояковогнутый диск с нормальным гемоглобином HbA"]], "pts": {"1": [0.62, 0.52], "2": [0.9, 0.14]}, "t": "Серповидноклеточная анемия (генная мутация)"}, {"sk": "diseases", "ref": "06.18", "n": 5, "gen": true, "id": "kariotip-trisomiya-21", "file": "topics/biology/osnovy-genetiki-izmenchivost/figures/kariotip-trisomiya-21.png", "marks": [["1", "Трисомия по 21-й паре", "Три хромосомы вместо двух — геномная мутация (синдром Дауна)"], ["2", "Половые хромосомы XY", "Мужской кариотип 47, XY, +21"]], "pts": {"1": [0.49, 0.89], "2": [0.95, 0.89]}, "t": "Кариограмма человека с синдромом Дауна (47, XY, +21)"}]};
